using System;
using System.Threading.Tasks;
using Unity.Netcode;
using Unity.Netcode.Transports.UTP;
using Unity.Services.Authentication;
using Unity.Services.Core;
using Unity.Services.Relay;
using Unity.Services.Relay.Models;
using UnityEngine;

/// <summary>
/// Manages Unity Relay connections for multiplayer gameplay.
/// Provides methods to create and join rooms via join codes.
/// </summary>
public class RelayManager : MonoBehaviour
{
    [Header("Configuration")]
    [SerializeField] private int maxPlayers = 4;
    [SerializeField] private bool debugMode = true;
    
    // Events
    public event Action<string> OnRoomCreated;
    public event Action<bool> OnRoomJoined;
    public event Action<string> OnError;
    
    // Connection state
    private bool isInitialized = false;
    private string currentJoinCode = string.Empty;

    #region Unity Lifecycle

    private void Awake()
    {
        // Persist across scenes if needed
        // DontDestroyOnLoad(gameObject);
    }

    #endregion

    #region Unity Services Initialization

    /// <summary>
    /// Initializes Unity Services and authenticates anonymously.
    /// Must be called before any Relay operations.
    /// </summary>
    public async Task<bool> InitializeUnityServices()
    {
        if (isInitialized)
        {
            LogDebug("Unity Services already initialized.");
            return true;
        }

        try
        {
            LogDebug("Initializing Unity Services...");
            
            // Initialize the Unity Services engine
            await UnityServices.InitializeAsync();
            
            // Authenticate anonymously if not signed in
            if (!AuthenticationService.Instance.IsSignedIn)
            {
                LogDebug("Signing in anonymously...");
                await AuthenticationService.Instance.SignInAnonymouslyAsync();
                LogDebug($"Signed in with Player ID: {AuthenticationService.Instance.PlayerId}");
            }
            
            isInitialized = true;
            LogDebug("Unity Services initialized successfully.");
            return true;
        }
        catch (Exception ex)
        {
            LogError($"Failed to initialize Unity Services: {ex.Message}");
            OnError?.Invoke($"Initialization failed: {ex.Message}");
            return false;
        }
    }

    #endregion

    #region Host Operations (Create Room)

    /// <summary>
    /// Creates a new Relay allocation and starts the host.
    /// Returns the join code that clients can use to join.
    /// </summary>
    public async Task<string> CreateRoom()
    {
        try
        {
            // Ensure Unity Services is initialized
            if (!await EnsureInitialized())
            {
                return null;
            }

            LogDebug($"Creating Relay allocation for {maxPlayers} players...");

            // Create a Relay allocation for (maxPlayers - 1) connections
            // -1 because host doesn't count as a connection
            Allocation allocation = await RelayService.Instance.CreateAllocationAsync(maxPlayers - 1);
            
            LogDebug($"Relay allocation created. Allocation ID: {allocation.AllocationId}");

            // Get the join code for this allocation
            string joinCode = await RelayService.Instance.GetJoinCodeAsync(allocation.AllocationId);
            currentJoinCode = joinCode;
            
            LogDebug($"Join code generated: {joinCode}");

            // Configure Unity Transport with Relay server data
            var transport = NetworkManager.Singleton.GetComponent<UnityTransport>();
            if (transport == null)
            {
                LogError("UnityTransport component not found on NetworkManager!");
                OnError?.Invoke("Transport component missing.");
                return null;
            }

            // Set Relay server data with DTLS connection type
            transport.SetHostRelayData(
                allocation.RelayServer.IpV4,
                (ushort)allocation.RelayServer.Port,
                allocation.AllocationIdBytes,
                allocation.Key,
                allocation.ConnectionData,
                isSecure: true
            );
            
            LogDebug("Unity Transport configured with Relay server data.");

            // Start as host
            if (!NetworkManager.Singleton.StartHost())
            {
                LogError("Failed to start as host!");
                OnError?.Invoke("Failed to start host.");
                return null;
            }

            LogDebug($"Host started successfully! Join code: {joinCode}");
            OnRoomCreated?.Invoke(joinCode);
            
            return joinCode;
        }
        catch (RelayServiceException ex)
        {
            LogError($"Relay Service Error: {ex.Message} (Reason: {ex.Reason})");
            OnError?.Invoke($"Relay error: {ex.Reason}");
            return null;
        }
        catch (Exception ex)
        {
            LogError($"Failed to create room: {ex.Message}");
            OnError?.Invoke($"Room creation failed: {ex.Message}");
            return null;
        }
    }

    #endregion

    #region Client Operations (Join Room)

    /// <summary>
    /// Joins an existing Relay allocation using a join code.
    /// Returns true if successfully joined.
    /// </summary>
    public async Task<bool> JoinRoom(string joinCode)
    {
        if (string.IsNullOrEmpty(joinCode))
        {
            LogError("Join code cannot be empty!");
            OnError?.Invoke("Invalid join code.");
            return false;
        }

        try
        {
            // Ensure Unity Services is initialized
            if (!await EnsureInitialized())
            {
                return false;
            }

            LogDebug($"Joining Relay allocation with code: {joinCode}");

            // Join the Relay allocation using the provided join code
            JoinAllocation joinAllocation = await RelayService.Instance.JoinAllocationAsync(joinCode);
            
            LogDebug($"Successfully joined allocation. Allocation ID: {joinAllocation.AllocationId}");

            // Configure Unity Transport with Relay server data
            var transport = NetworkManager.Singleton.GetComponent<UnityTransport>();
            if (transport == null)
            {
                LogError("UnityTransport component not found on NetworkManager!");
                OnError?.Invoke("Transport component missing.");
                return false;
            }

            // Set Relay server data with DTLS connection type
            transport.SetClientRelayData(
                joinAllocation.RelayServer.IpV4,
                (ushort)joinAllocation.RelayServer.Port,
                joinAllocation.AllocationIdBytes,
                joinAllocation.Key,
                joinAllocation.ConnectionData,
                joinAllocation.HostConnectionData,
                isSecure: true
            );
            
            LogDebug("Unity Transport configured with Relay server data.");

            // Start as client
            if (!NetworkManager.Singleton.StartClient())
            {
                LogError("Failed to start as client!");
                OnError?.Invoke("Failed to connect.");
                return false;
            }

            currentJoinCode = joinCode;
            LogDebug("Client started successfully!");
            OnRoomJoined?.Invoke(true);
            
            return true;
        }
        catch (RelayServiceException ex)
        {
            LogError($"Relay Service Error: {ex.Message} (Reason: {ex.Reason})");
            OnError?.Invoke($"Join failed: {ex.Reason}");
            OnRoomJoined?.Invoke(false);
            return false;
        }
        catch (Exception ex)
        {
            LogError($"Failed to join room: {ex.Message}");
            OnError?.Invoke($"Join failed: {ex.Message}");
            OnRoomJoined?.Invoke(false);
            return false;
        }
    }

    #endregion

    #region Disconnection

    /// <summary>
    /// Disconnects from the current Relay session and shuts down NetworkManager.
    /// </summary>
    public void LeaveRoom()
    {
        try
        {
            if (NetworkManager.Singleton != null && NetworkManager.Singleton.IsListening)
            {
                LogDebug("Shutting down NetworkManager...");
                NetworkManager.Singleton.Shutdown();
            }

            currentJoinCode = string.Empty;
            LogDebug("Left room successfully.");
        }
        catch (Exception ex)
        {
            LogError($"Error leaving room: {ex.Message}");
        }
    }

    #endregion

    #region Helper Methods

    /// <summary>
    /// Ensures Unity Services is initialized before performing operations.
    /// </summary>
    private async Task<bool> EnsureInitialized()
    {
        if (!isInitialized)
        {
            return await InitializeUnityServices();
        }
        return true;
    }

    /// <summary>
    /// Gets the current join code (if host).
    /// </summary>
    public string GetCurrentJoinCode()
    {
        return currentJoinCode;
    }

    /// <summary>
    /// Checks if currently connected to a Relay session.
    /// </summary>
    public bool IsConnected()
    {
        return NetworkManager.Singleton != null && NetworkManager.Singleton.IsListening;
    }

    /// <summary>
    /// Checks if this client is the host.
    /// </summary>
    public bool IsHost()
    {
        return NetworkManager.Singleton != null && NetworkManager.Singleton.IsHost;
    }

    #endregion

    #region Debug Logging

    private void LogDebug(string message)
    {
        if (debugMode)
        {
            Debug.Log($"[RelayManager] {message}");
        }
    }

    private void LogError(string message)
    {
        Debug.LogError($"[RelayManager] {message}");
    }

    #endregion

    #region Cleanup

    private void OnDestroy()
    {
        LeaveRoom();
    }

    #endregion
}

using System.Collections;
using Unity.Netcode;
using UnityEngine;
using TMPro;

namespace Tanks.Complete
{
    /// <summary>
    /// NetworkGameManager wraps GameManager để thêm multiplayer functionality.
    /// Hoạt động như network layer giữa clients và local GameManager logic.
    /// Server authority cho game state, rounds, và scoring.
    /// </summary>
    public class NetworkGameManager : NetworkBehaviour
    {
        [Header("References")]
        public GameManager m_LocalGameManager;  // Reference to local GameManager
        
        [Header("Network State")]
        // Game state synchronized across all clients
        private NetworkVariable<GameManager.GameState> m_NetworkGameState = new NetworkVariable<GameManager.GameState>(
            GameManager.GameState.MainMenu,
            NetworkVariableReadPermission.Everyone,
            NetworkVariableWritePermission.Server
        );
        
        // Current round number synchronized
        private NetworkVariable<int> m_NetworkRoundNumber = new NetworkVariable<int>(
            0,
            NetworkVariableReadPermission.Everyone,
            NetworkVariableWritePermission.Server
        );
        
        // Number of active players
        private NetworkVariable<int> m_NetworkPlayerCount = new NetworkVariable<int>(
            0,
            NetworkVariableReadPermission.Everyone,
            NetworkVariableWritePermission.Server
        );
        
        // Current game phase for synchronization
        public enum GamePhase
        {
            Waiting,
            RoundStarting,
            RoundPlaying,
            RoundEnding,
            GameOver
        }
        
        private NetworkVariable<GamePhase> m_CurrentPhase = new NetworkVariable<GamePhase>(
            GamePhase.Waiting,
            NetworkVariableReadPermission.Everyone,
            NetworkVariableWritePermission.Server
        );
        
        // Track player scores (client ID -> wins)
        private NetworkList<PlayerScore> m_PlayerScores;
        
        // Structure to hold player score data
        public struct PlayerScore : INetworkSerializable, System.IEquatable<PlayerScore>
        {
            public ulong ClientId;
            public int Wins;
            public Color PlayerColor;
            
            public void NetworkSerialize<T>(BufferSerializer<T> serializer) where T : IReaderWriter
            {
                serializer.SerializeValue(ref ClientId);
                serializer.SerializeValue(ref Wins);
                serializer.SerializeValue(ref PlayerColor);
            }
            
            public bool Equals(PlayerScore other)
            {
                return ClientId == other.ClientId && Wins == other.Wins;
            }
        }
        
        private void Awake()
        {
            // Initialize NetworkList in Awake to avoid memory leaks
            m_PlayerScores = new NetworkList<PlayerScore>();
        }
        
        public override void OnNetworkSpawn()
        {
            base.OnNetworkSpawn();
            
            if (IsServer)
            {
                // Server listens for client connections
                NetworkManager.Singleton.OnClientConnectedCallback += OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback += OnClientDisconnected;
                
                // Subscribe to list changes
                m_PlayerScores.OnListChanged += OnServerScoresChanged;
            }
            
            if (IsClient)
            {
                // Clients subscribe to network variable changes
                m_NetworkGameState.OnValueChanged += OnGameStateChanged;
                m_NetworkRoundNumber.OnValueChanged += OnRoundNumberChanged;
                m_CurrentPhase.OnValueChanged += OnPhaseChanged;
                m_PlayerScores.OnListChanged += OnClientScoresChanged;
            }
        }
        
        public override void OnNetworkDespawn()
        {
            base.OnNetworkDespawn();
            
            if (IsServer)
            {
                if (NetworkManager.Singleton != null)
                {
                    NetworkManager.Singleton.OnClientConnectedCallback -= OnClientConnected;
                    NetworkManager.Singleton.OnClientDisconnectCallback -= OnClientDisconnected;
                }
            }
        }
        
        #region Server Callbacks
        
        private void OnClientConnected(ulong clientId)
        {
            Debug.Log($"[Server] Client {clientId} connected. Total players: {NetworkManager.Singleton.ConnectedClients.Count}");
            
            // Add player to scores list
            m_PlayerScores.Add(new PlayerScore 
            { 
                ClientId = clientId, 
                Wins = 0,
                PlayerColor = GetPlayerColor(m_PlayerScores.Count)
            });
            
            m_NetworkPlayerCount.Value = NetworkManager.Singleton.ConnectedClients.Count;
            
            // Notify all clients about new player
            NotifyPlayerJoinedClientRpc(clientId);
        }
        
        private void OnClientDisconnected(ulong clientId)
        {
            Debug.Log($"[Server] Client {clientId} disconnected");
            
            // Remove player from scores
            for (int i = 0; i < m_PlayerScores.Count; i++)
            {
                if (m_PlayerScores[i].ClientId == clientId)
                {
                    m_PlayerScores.RemoveAt(i);
                    break;
                }
            }
            
            m_NetworkPlayerCount.Value = NetworkManager.Singleton.ConnectedClients.Count;
            
            // Notify all clients
            NotifyPlayerLeftClientRpc(clientId);
        }
        
        private Color GetPlayerColor(int index)
        {
            Color[] colors = new Color[] 
            { 
                Color.red, 
                Color.blue, 
                Color.green, 
                Color.yellow 
            };
            return colors[index % colors.Length];
        }
        
        private void OnServerScoresChanged(NetworkListEvent<PlayerScore> changeEvent)
        {
            Debug.Log($"[Server] Scores changed. Total players: {m_PlayerScores.Count}");
        }
        
        #endregion
        
        #region Client Callbacks
        
        private void OnGameStateChanged(GameManager.GameState oldState, GameManager.GameState newState)
        {
            Debug.Log($"[Client] Game state changed from {oldState} to {newState}");
        }
        
        private void OnRoundNumberChanged(int oldRound, int newRound)
        {
            Debug.Log($"[Client] Round changed from {oldRound} to {newRound}");
        }
        
        private void OnPhaseChanged(GamePhase oldPhase, GamePhase newPhase)
        {
            Debug.Log($"[Client] Phase changed from {oldPhase} to {newPhase}");
        }
        
        private void OnClientScoresChanged(NetworkListEvent<PlayerScore> changeEvent)
        {
            Debug.Log($"[Client] Scores updated. Total players: {m_PlayerScores.Count}");
        }
        
        #endregion
        
        #region Server RPCs - Client to Server
        
        /// <summary>
        /// Client requests to start the game when they're ready
        /// </summary>
        [ServerRpc]
        public void RequestStartGameServerRpc(ServerRpcParams rpcParams = default)
        {
            ulong clientId = rpcParams.Receive.SenderClientId;
            Debug.Log($"[Server] Client {clientId} requested to start game");
            
            // Only host can start the game
            if (clientId == NetworkManager.Singleton.LocalClientId)
            {
                StartNetworkGame();
            }
        }
        
        /// <summary>
        /// Notify server when a tank dies
        /// </summary>
        [ServerRpc]
        public void OnTankDeathServerRpc(ulong tankOwnerClientId, ServerRpcParams rpcParams = default)
        {
            Debug.Log($"[Server] Tank owned by client {tankOwnerClientId} died");
            
            // Server will check win conditions
            CheckRoundEnd();
        }
        
        #endregion
        
        #region Client RPCs - Server to Clients
        
        [ClientRpc]
        private void NotifyPlayerJoinedClientRpc(ulong clientId)
        {
            Debug.Log($"[Client] Player {clientId} joined the game");
        }
        
        [ClientRpc]
        private void NotifyPlayerLeftClientRpc(ulong clientId)
        {
            Debug.Log($"[Client] Player {clientId} left the game");
        }
        
        /// <summary>
        /// Notify all clients that a round is starting
        /// </summary>
        [ClientRpc]
        public void StartRoundClientRpc(int roundNumber)
        {
            Debug.Log($"[Client] Round {roundNumber} starting!");
            
            // Update local UI
            if (m_LocalGameManager != null)
            {
                // Trigger local game manager's round start visuals
                // This would update the "ROUND X" text
            }
        }
        
        /// <summary>
        /// Notify all clients about round results
        /// </summary>
        [ClientRpc]
        public void EndRoundClientRpc(ulong winnerClientId, string message)
        {
            Debug.Log($"[Client] Round ended. Winner: {winnerClientId}");
            
            // Update local UI with results
            UpdateEndMessageClientRpc(message);
        }
        
        /// <summary>
        /// Update UI text on all clients
        /// </summary>
        [ClientRpc]
        public void UpdateTitleTextClientRpc(string message)
        {
            var textRef = FindAnyObjectByType<MessageTextReference>(FindObjectsInactive.Include);
            if (textRef != null)
            {
                textRef.Text.text = message;
            }
        }
        
        /// <summary>
        /// Update end message on all clients
        /// </summary>
        [ClientRpc]
        private void UpdateEndMessageClientRpc(string message)
        {
            var textRef = FindAnyObjectByType<MessageTextReference>(FindObjectsInactive.Include);
            if (textRef != null)
            {
                textRef.Text.text = message;
            }
        }
        
        /// <summary>
        /// Enable tank controls on all clients
        /// </summary>
        [ClientRpc]
        public void EnableTankControlsClientRpc()
        {
            // Each client enables control only for their own tank
            // This is handled by TankMovement/TankShooting checking IsOwner
        }
        
        /// <summary>
        /// Disable tank controls on all clients
        /// </summary>
        [ClientRpc]
        public void DisableTankControlsClientRpc()
        {
            // Each client disables control for their tank
        }
        
        #endregion
        
        #region Game Logic - Server Only
        
        /// <summary>
        /// Start the networked game (Server only)
        /// </summary>
        public void StartNetworkGame()
        {
            if (!IsServer) return;
            
            Debug.Log("[Server] Starting network game");
            
            m_NetworkGameState.Value = GameManager.GameState.Game;
            m_NetworkRoundNumber.Value = 0;
            m_CurrentPhase.Value = GamePhase.RoundStarting;
            
            // Spawn tanks for all connected players
            SpawnAllTanks();
            
            // Start game loop
            StartCoroutine(NetworkGameLoop());
        }
        
        /// <summary>
        /// Spawn tanks for all connected clients (Server only)
        /// </summary>
        private void SpawnAllTanks()
        {
            if (!IsServer) return;
            
            int playerIndex = 0;
            foreach (var clientId in NetworkManager.Singleton.ConnectedClientsIds)
            {
                SpawnTankForPlayer(clientId, playerIndex);
                playerIndex++;
            }
        }
        
        /// <summary>
        /// Spawn a tank for specific player (Server only)
        /// </summary>
        private void SpawnTankForPlayer(ulong clientId, int spawnIndex)
        {
            if (!IsServer) return;
            
            // Get spawn point from local GameManager
            if (m_LocalGameManager != null && spawnIndex < m_LocalGameManager.m_SpawnPoints.Length)
            {
                var spawnPoint = m_LocalGameManager.m_SpawnPoints[spawnIndex];
                
                // Get the appropriate tank prefab
                GameObject tankPrefab = GetTankPrefab(spawnIndex);
                
                if (tankPrefab != null)
                {
                    GameObject tankInstance = Instantiate(
                        tankPrefab, 
                        spawnPoint.m_SpawnPoint.position, 
                        spawnPoint.m_SpawnPoint.rotation
                    );
                    
                    NetworkObject netObj = tankInstance.GetComponent<NetworkObject>();
                    if (netObj != null)
                    {
                        // Spawn as player object for ownership
                        netObj.SpawnAsPlayerObject(clientId);
                        
                        Debug.Log($"[Server] Spawned tank for client {clientId} at index {spawnIndex}");
                    }
                }
            }
        }
        
        private GameObject GetTankPrefab(int index)
        {
            if (m_LocalGameManager == null) return null;
            
            switch (index)
            {
                case 0: return m_LocalGameManager.m_Tank1Prefab;
                case 1: return m_LocalGameManager.m_Tank2Prefab;
                case 2: return m_LocalGameManager.m_Tank3Prefab;
                case 3: return m_LocalGameManager.m_Tank4Prefab;
                default: return m_LocalGameManager.m_Tank1Prefab;
            }
        }
        
        /// <summary>
        /// Main game loop for networked game (Server only)
        /// </summary>
        private IEnumerator NetworkGameLoop()
        {
            if (!IsServer) yield break;
            
            while (m_NetworkGameState.Value == GameManager.GameState.Game)
            {
                // Round Starting Phase
                yield return StartCoroutine(NetworkRoundStarting());
                
                // Round Playing Phase
                yield return StartCoroutine(NetworkRoundPlaying());
                
                // Round Ending Phase
                yield return StartCoroutine(NetworkRoundEnding());
                
                // Check for game winner
                ulong gameWinner = CheckGameWinner();
                if (gameWinner != 0)
                {
                    m_CurrentPhase.Value = GamePhase.GameOver;
                    UpdateTitleTextClientRpc($"PLAYER {gameWinner} WINS THE GAME!");
                    yield break;
                }
            }
        }
        
        private IEnumerator NetworkRoundStarting()
        {
            m_CurrentPhase.Value = GamePhase.RoundStarting;
            m_NetworkRoundNumber.Value++;
            
            // Reset all tanks to spawn positions
            ResetAllTanks();
            
            // Notify clients
            UpdateTitleTextClientRpc($"ROUND {m_NetworkRoundNumber.Value}");
            StartRoundClientRpc(m_NetworkRoundNumber.Value);
            
            // Wait for start delay
            yield return new WaitForSeconds(m_LocalGameManager != null ? m_LocalGameManager.m_StartDelay : 3f);
        }
        
        private IEnumerator NetworkRoundPlaying()
        {
            m_CurrentPhase.Value = GamePhase.RoundPlaying;
            
            // Clear UI
            UpdateTitleTextClientRpc("");
            
            // Enable tank controls
            EnableTankControlsClientRpc();
            
            // Wait until only one tank left
            while (!CheckOneTankLeft())
            {
                yield return null;
            }
        }
        
        private IEnumerator NetworkRoundEnding()
        {
            m_CurrentPhase.Value = GamePhase.RoundEnding;
            
            // Disable tank controls
            DisableTankControlsClientRpc();
            
            // Get round winner and update scores
            ulong winnerClientId = GetRoundWinner();
            if (winnerClientId != 0)
            {
                UpdatePlayerScore(winnerClientId);
            }
            
            // Generate and send end message
            string endMessage = GenerateEndMessage(winnerClientId);
            EndRoundClientRpc(winnerClientId, endMessage);
            
            // Wait for end delay
            yield return new WaitForSeconds(m_LocalGameManager != null ? m_LocalGameManager.m_EndDelay : 3f);
        }
        
        private bool CheckOneTankLeft()
        {
            // Count active tanks
            int activeTanks = 0;
            foreach (var netObj in FindObjectsByType<NetworkObject>(FindObjectsSortMode.None))
            {
                if (netObj.CompareTag("Player") && netObj.IsSpawned)
                {
                    var health = netObj.GetComponent<TankHealth>();
                    if (health != null && health.gameObject.activeSelf)
                    {
                        activeTanks++;
                    }
                }
            }
            
            return activeTanks <= 1;
        }
        
        private void CheckRoundEnd()
        {
            // This is called when a tank dies
            // The coroutine will handle checking OneTankLeft
        }
        
        private ulong GetRoundWinner()
        {
            // Find the last active tank
            foreach (var netObj in FindObjectsByType<NetworkObject>(FindObjectsSortMode.None))
            {
                if (netObj.CompareTag("Player") && netObj.IsSpawned)
                {
                    var health = netObj.GetComponent<TankHealth>();
                    if (health != null && health.gameObject.activeSelf)
                    {
                        return netObj.OwnerClientId;
                    }
                }
            }
            
            return 0; // Draw
        }
        
        private void UpdatePlayerScore(ulong clientId)
        {
            for (int i = 0; i < m_PlayerScores.Count; i++)
            {
                if (m_PlayerScores[i].ClientId == clientId)
                {
                    var score = m_PlayerScores[i];
                    score.Wins++;
                    m_PlayerScores[i] = score;
                    break;
                }
            }
        }
        
        private ulong CheckGameWinner()
        {
            int numRoundsToWin = m_LocalGameManager != null ? m_LocalGameManager.m_NumRoundsToWin : 5;
            
            foreach (var score in m_PlayerScores)
            {
                if (score.Wins >= numRoundsToWin)
                {
                    return score.ClientId;
                }
            }
            
            return 0;
        }
        
        private string GenerateEndMessage(ulong winnerClientId)
        {
            string message = winnerClientId == 0 ? "DRAW!" : $"PLAYER {winnerClientId} WINS THE ROUND!";
            message += "\n\n\n\n";
            
            foreach (var score in m_PlayerScores)
            {
                message += $"PLAYER {score.ClientId}: {score.Wins} WINS\n";
            }
            
            return message;
        }
        
        /// <summary>
        /// Reset all tanks to their spawn positions (Server only).
        /// Called at the start of each round.
        /// </summary>
        private void ResetAllTanks()
        {
            if (!IsServer)
                return;

            int spawnIndex = 0;
            
            // Find all spawned player tanks
            foreach (var netObj in FindObjectsByType<NetworkObject>(FindObjectsSortMode.None))
            {
                if (netObj.CompareTag("Player") && netObj.IsSpawned)
                {
                    // Get spawn point for this tank
                    if (m_LocalGameManager != null && spawnIndex < m_LocalGameManager.m_SpawnPoints.Length)
                    {
                        var spawnPoint = m_LocalGameManager.m_SpawnPoints[spawnIndex];
                        
                        // Reset position and rotation
                        netObj.transform.position = spawnPoint.m_SpawnPoint.position;
                        netObj.transform.rotation = spawnPoint.m_SpawnPoint.rotation;
                        
                        // Reset tank health
                        TankHealth health = netObj.GetComponent<TankHealth>();
                        if (health != null)
                        {
                            health.gameObject.SetActive(true);
                            // Health will be reset via OnEnable -> NetworkVariable
                        }
                        
                        // Reset tank movement (velocity, etc.)
                        TankMovement movement = netObj.GetComponent<TankMovement>();
                        if (movement != null && movement.Rigidbody != null)
                        {
                            movement.Rigidbody.linearVelocity = Vector3.zero;
                            movement.Rigidbody.angularVelocity = Vector3.zero;
                        }
                        
                        spawnIndex++;
                    }
                }
            }
            
            Debug.Log($"[NetworkGameManager] Reset {spawnIndex} tanks to spawn positions");
        }
        
        #endregion
    }
}

using System;
using TMPro;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.UI;

public class NetworkMenu : MonoBehaviour
{
    [Header("UI Panels")]
        [SerializeField] private GameObject mainMenuPanel;
        [SerializeField] private GameObject createRoomPanel;
        [SerializeField] private GameObject joinRoomPanel;
        [SerializeField] private GameObject waitingRoomPanel;

        [Header("Main Menu Buttons")]
        [SerializeField] private Button createRoomButton;
        [SerializeField] private Button joinRoomButton;

        [Header("Create Room UI")]
        [SerializeField] private TextMeshProUGUI joinCodeText;
        [SerializeField] private Button copyJoinCodeButton;
        [SerializeField] private Button cancelCreateButton;

        [Header("Join Room UI")]
        [SerializeField] private TMP_InputField joinCodeInputField;
        [SerializeField] private Button confirmJoinButton;
        [SerializeField] private Button cancelJoinButton;

        [Header("Waiting Room UI")]
        [SerializeField] private TextMeshProUGUI statusText;
        [SerializeField] private TextMeshProUGUI playerListText;
        [SerializeField] private Button leaveRoomButton;

        [Header("References")]
        [SerializeField] private RelayManager relayManager;

        private void Awake()
        {
            // Find RelayManager if not assigned
            if (relayManager == null)
            {
                relayManager = FindFirstObjectByType<RelayManager>();
                if (relayManager == null)
                {
                    Debug.LogError("[NetworkMenu] RelayManager not found in scene!");
                }
            }

            SetupButtonListeners();
            ShowMainMenu();
        }

        private void OnEnable()
        {
            if (relayManager != null)
            {
                relayManager.OnRoomCreated += HandleRoomCreated;
                relayManager.OnRoomJoined += HandleRoomJoined;
                relayManager.OnError += HandleError;
            }

            if (NetworkManager.Singleton != null)
            {
                NetworkManager.Singleton.OnClientConnectedCallback += OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback += OnClientDisconnected;
            }
        }

        private void OnDisable()
        {
            if (relayManager != null)
            {
                relayManager.OnRoomCreated -= HandleRoomCreated;
                relayManager.OnRoomJoined -= HandleRoomJoined;
                relayManager.OnError -= HandleError;
            }

            if (NetworkManager.Singleton != null)
            {
                NetworkManager.Singleton.OnClientConnectedCallback -= OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback -= OnClientDisconnected;
            }
        }

        #region Button Setup

        private void SetupButtonListeners()
        {
            // Main menu buttons
            if (createRoomButton != null)
                createRoomButton.onClick.AddListener(OnCreateRoomClicked);
            
            if (joinRoomButton != null)
                joinRoomButton.onClick.AddListener(OnJoinRoomClicked);

            // Create room buttons
            if (copyJoinCodeButton != null)
                copyJoinCodeButton.onClick.AddListener(OnCopyJoinCodeClicked);
            
            if (cancelCreateButton != null)
                cancelCreateButton.onClick.AddListener(OnCancelCreateClicked);

            // Join room buttons
            if (confirmJoinButton != null)
                confirmJoinButton.onClick.AddListener(OnConfirmJoinClicked);
            
            if (cancelJoinButton != null)
                cancelJoinButton.onClick.AddListener(OnCancelJoinClicked);

            // Waiting room buttons
            if (leaveRoomButton != null)
                leaveRoomButton.onClick.AddListener(OnLeaveRoomClicked);
        }

        #endregion

        #region Button Handlers

        private async void OnCreateRoomClicked()
        {
            Debug.Log("[NetworkMenu] Create Room button clicked");
            
            if (relayManager == null)
            {
                Debug.LogError("[NetworkMenu] RelayManager is not assigned!");
                return;
            }

            // Show waiting state
            ShowCreateRoomPanel();
            UpdateJoinCodeText("Creating room...");

            // Create room via Relay
            string joinCode = await relayManager.CreateRoom();

            if (!string.IsNullOrEmpty(joinCode))
            {
                UpdateJoinCodeText(joinCode);
                Debug.Log($"[NetworkMenu] Room created with code: {joinCode}");
            }
            else
            {
                ShowMainMenu();
                Debug.LogError("[NetworkMenu] Failed to create room");
            }
        }

        private void OnJoinRoomClicked()
        {
            Debug.Log("[NetworkMenu] Join Room button clicked");
            ShowJoinRoomPanel();
        }

        private async void OnConfirmJoinClicked()
        {
            if (relayManager == null)
            {
                Debug.LogError("[NetworkMenu] RelayManager is not assigned!");
                return;
            }

            string joinCode = joinCodeInputField.text.Trim().ToUpper();
            
            if (string.IsNullOrEmpty(joinCode))
            {
                Debug.LogWarning("[NetworkMenu] Join code is empty");
                return;
            }

            Debug.Log($"[NetworkMenu] Attempting to join room with code: {joinCode}");
            
            // Show waiting state
            ShowWaitingRoom("Joining room...", "");
            
            // Join room via Relay
            bool success = await relayManager.JoinRoom(joinCode);

            if (success)
            {
                UpdateStatusText("Connected! Waiting for game to start...");
                Debug.Log("[NetworkMenu] Successfully joined room");
            }
            else
            {
                ShowJoinRoomPanel();
                Debug.LogError("[NetworkMenu] Failed to join room");
            }
        }

        private void OnCopyJoinCodeClicked()
        {
            if (relayManager != null)
            {
                string joinCode = relayManager.GetCurrentJoinCode();
                if (!string.IsNullOrEmpty(joinCode))
                {
                    GUIUtility.systemCopyBuffer = joinCode;
                    Debug.Log($"[NetworkMenu] Join code copied to clipboard: {joinCode}");
                }
            }
        }

        private void OnCancelCreateClicked()
        {
            if (relayManager != null)
            {
                relayManager.LeaveRoom();
            }
            ShowMainMenu();
        }

        private void OnCancelJoinClicked()
        {
            ShowMainMenu();
        }

        private void OnLeaveRoomClicked()
        {
            if (relayManager != null)
            {
                relayManager.LeaveRoom();
            }
            ShowMainMenu();
        }

        #endregion

        #region Relay Event Handlers

        private void HandleRoomCreated(string joinCode)
        {
            Debug.Log($"[NetworkMenu] Room created event: {joinCode}");
            ShowWaitingRoom($"Room Created!\nJoin Code: {joinCode}", "Waiting for players...");
        }

        private void HandleRoomJoined(bool success)
        {
            if (success)
            {
                Debug.Log("[NetworkMenu] Successfully joined room");
                ShowWaitingRoom("Connected!", "Waiting for game to start...");
            }
            else
            {
                Debug.LogError("[NetworkMenu] Failed to join room");
                ShowJoinRoomPanel();
            }
        }

        private void HandleError(string errorMessage)
        {
            Debug.LogError($"[NetworkMenu] Relay error: {errorMessage}");
            // Could show error popup here
            ShowMainMenu();
        }

        #endregion

        #region Network Callbacks

        private void OnClientConnected(ulong clientId)
        {
            Debug.Log($"[NetworkMenu] Client connected: {clientId}");
            UpdatePlayerList();
        }

        private void OnClientDisconnected(ulong clientId)
        {
            Debug.Log($"[NetworkMenu] Client disconnected: {clientId}");
            
            // If we disconnected, return to main menu
            if (NetworkManager.Singleton != null && clientId == NetworkManager.Singleton.LocalClientId)
            {
                ShowMainMenu();
            }
            else
            {
                UpdatePlayerList();
            }
        }

        #endregion

        #region UI Panel Management

        private void ShowMainMenu()
        {
            SetPanelActive(mainMenuPanel, true);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, false);
        }

        private void ShowCreateRoomPanel()
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, true);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, false);
        }

        private void ShowJoinRoomPanel()
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, true);
            SetPanelActive(waitingRoomPanel, false);
            
            if (joinCodeInputField != null)
            {
                joinCodeInputField.text = "";
            }
        }

        private void ShowWaitingRoom(string status, string playerInfo)
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, true);
            
            UpdateStatusText(status);
            UpdatePlayerListText(playerInfo);
        }

        private void SetPanelActive(GameObject panel, bool active)
        {
            if (panel != null)
            {
                panel.SetActive(active);
            }
        }

        #endregion

        #region UI Updates

        private void UpdateJoinCodeText(string code)
        {
            if (joinCodeText != null)
            {
                joinCodeText.text = code;
            }
        }

        private void UpdateStatusText(string status)
        {
            if (statusText != null)
            {
                statusText.text = status;
            }
        }

        private void UpdatePlayerListText(string playerInfo)
        {
            if (playerListText != null)
            {
                playerListText.text = playerInfo;
            }
        }

        private void UpdatePlayerList()
        {
            if (NetworkManager.Singleton == null || !NetworkManager.Singleton.IsListening)
            {
                UpdatePlayerListText("Not connected");
                return;
            }

            int connectedPlayers = NetworkManager.Singleton.ConnectedClientsList.Count;
            string playerText = $"Players: {connectedPlayers}";
            
            if (relayManager != null && relayManager.IsHost())
            {
                playerText += " (You are Host)";
            }
            
            UpdatePlayerListText(playerText);
        }

        #endregion

        #region Legacy Support (for backwards compatibility)

        // Keep old methods for scenes that might reference them
        [Obsolete("Use Create/Join Room buttons instead")]
        private void Hide()
        {
            gameObject.SetActive(false);
        }

        #endregion
    }

using TMPro;
using UnityEngine;
using Button = UnityEngine.UI.Button;
using Image = UnityEngine.UI.Image;

namespace Tanks.Complete
{
    // Class handling on "slot" in the main menu, which is an entry that show a tank preview, display its stat and allow
    // to add that tank to the game or not and change who control it (p1, p2 or computer)
    public class StartMenuSlot : MonoBehaviour
    {
        public Color m_SlotColor;                       // The color the tank in that slot will take
        
        [Header("References")]
        public RectTransform m_TankPreviewPosition;     // The Transform on which to place the Tank preview so it display at the right place on screen
        public TextMeshProUGUI m_TankStats;             // The Text to use to display the tank stats
        public Button m_AddControlButton;               // The button on which when clicked the tank get added to the current game

        public RectTransform m_ControlChoiceRoot;       // The root of which all the control choice buttons are parented to
        public Button m_P1ControlButton;                // the button that make this tank controlled by p1
        public Button m_P2ControlButton;                // the button that make this tank controlled by p2
        public Button m_ComputerControlButton;          // the button that make this tank controlled by the computer
        public Button m_OffControlButton;               // the button that remove that tank from the currently used tanks

        public Image BackgroundImage;                   // The Image that is the background of the whole slot
        public Sprite OpenSlotBackground;               // The sprite to use when the slot is open (still not used by anyone)
        public Sprite UsedSlotBackground;               // The sprite to use when the slot is used (controlled by p1/p2 or computer)

        public GameObject TankPreview { get; set; }         // The preview instance that show this tank rotating in the menu
        public GameObject TankPrefab { get; private set; }  // The prefab this slot is based on
        public int PlayerControlling { get; set; }          // Which player control this, 1 or 2 (will be -1 for computer)
        public bool IsOpen { get; set; }                    // Is the slot open (not join the game yet) or not (already assigned to p1/p2 or computer)
        public bool IsComputer { get; set; }                // Is the slot used by a computer controlled tank or a player controlled one
        
        private Camera m_MenuCamera;                        // The Camera used to display the menu

        // Start is called once before the first execution of Update after the MonoBehaviour is created
        void Awake()
        {
            m_MenuCamera = GetComponentInParent<Camera>();
            IsOpen = true;

            //On mobile platform you can only use one player, so we disabled p2
            if (Application.isMobilePlatform)
            {
                m_P2ControlButton.gameObject.SetActive(false);
            }

            BackgroundImage.sprite = OpenSlotBackground;
        }
        
        private void Update()
        {
            // If we have a preview slowly rotate it
            if (TankPreview != null)
            {
                TankPreview.transform.Rotate(Vector3.up, 45.0f * Time.deltaTime);
            }
        }

        public void AddTank()
        {
            m_AddControlButton.gameObject.SetActive(false);
            m_ControlChoiceRoot.gameObject.SetActive(true);

            IsOpen = false;
            BackgroundImage.sprite = UsedSlotBackground;
        }

        public void RemoveTank()
        {
            m_AddControlButton.gameObject.SetActive(true);
            m_ControlChoiceRoot.gameObject.SetActive(false);

            SetPlayerControlling(-1);

            IsOpen = true;
            BackgroundImage.sprite = OpenSlotBackground;
        }

        public void SetPlayerControlling(int playerNumber)
        {
            //re-enable the button for the current controller as we now can re-select it again
            if (PlayerControlling == 1)
                m_P1ControlButton.interactable = true;
            else if (PlayerControlling == 2)
                m_P2ControlButton.interactable = true;
            else if (PlayerControlling == -1)
                m_ComputerControlButton.interactable = true;
            
            // change the controller 
            PlayerControlling = playerNumber;
            
            // then disable the associated button and set if its a computer or not 
            switch(playerNumber)
            {
                case 1:
                    m_P1ControlButton.interactable = false;
                    IsComputer = false;
                    break;
                case 2:
                    m_P2ControlButton.interactable = false;
                    IsComputer = false;
                    break;
                case -1:
                    m_ComputerControlButton.interactable = false;
                    IsComputer = true;
                    break;
            }
        }

        public void SetTankPreview(GameObject prefab)
        {
            // If we already have a tank preview, destroy it
            if (TankPreview != null)
            {
                Destroy(TankPreview);
            }

            //assign the right prefab
            TankPrefab = prefab;
            //then instantiate it as the preview
            TankPreview = Instantiate(prefab);
            
            // get reference to all components
            var move = TankPreview.GetComponent<TankMovement> ();
            var shoot = TankPreview.GetComponent<TankShooting> ();
            var health = TankPreview.GetComponent<TankHealth>();

            // disable them, as this is a visual only preview and doesn't need to react to any gameplay like user input etc.
            move.enabled = false;
            shoot.enabled = false;

            // update the tank stats text with this tank stats
            m_TankStats.text = $"Speed {move.m_Speed}\nDamage {shoot.m_MaxDamage}\nHealth: {health.m_StartingHealth}";
            
            //move it to the right preview position so it appears in the right spot on screen
            var position = m_MenuCamera.WorldToScreenPoint(m_TankPreviewPosition.position);
            TankPreview.transform.position =
                m_MenuCamera.ScreenToWorldPoint(position) + Vector3.back * 3.0f;
            
            // go through all renderers of that tank
            MeshRenderer[] renderers = TankPreview.GetComponentsInChildren<MeshRenderer>();
            for (int i = 0; i < renderers.Length; i++)
            {
                var renderer = renderers[i];
                for (int j = 0; j < renderer.materials.Length; ++j)
                {
                    // then when we find the TankColor material
                    if (renderer.materials[j].name.Contains("TankColor"))
                    {
                        // Set its color to the slot color
                        renderer.materials[j].color = m_SlotColor;
                    }
                }
            }
            
            //Disable all audio
            var audioSource = TankPreview.GetComponentsInChildren<AudioSource>();
            foreach (var source in audioSource)
            {
                Destroy(source);
            }
        }
    }
}

