using UnityEngine;
using UnityEditor;
using UnityEngine.UI;
using TMPro;
using System.Reflection;

public class LobbyUIGenerator : MonoBehaviour
{
    public static void GenerateLobbyUI()
    {
        GameObject canvasObj = GameObject.Find("Canvas");
        if (canvasObj == null)
        {
            canvasObj = new GameObject("Canvas");
            canvasObj.AddComponent<Canvas>().renderMode = RenderMode.ScreenSpaceOverlay;
            canvasObj.AddComponent<CanvasScaler>();
            canvasObj.AddComponent<GraphicRaycaster>();
        }

        GameObject networkMenuObj = GameObject.Find("NetworkMenu");
        if (networkMenuObj == null)
        {
            Debug.LogError("NetworkMenu object not found!");
            return;
        }
        NetworkMenu networkMenu = networkMenuObj.GetComponent<NetworkMenu>();

        // Helper to create panel
        GameObject CreatePanel(string name, bool active)
        {
            GameObject panel = new GameObject(name);
            panel.transform.SetParent(canvasObj.transform, false);
            RectTransform rect = panel.AddComponent<RectTransform>();
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;

            // Add background image
            Image img = panel.AddComponent<Image>();
            img.color = new Color(0, 0, 0, 0.8f);

            panel.SetActive(active);
            return panel;
        }

        // Helper to create button
        Button CreateButton(GameObject parent, string name, string text, Vector2 pos, Vector2 size)
        {
            GameObject btnObj = new GameObject(name);
            btnObj.transform.SetParent(parent.transform, false);
            RectTransform rect = btnObj.AddComponent<RectTransform>();
            rect.anchoredPosition = pos;
            rect.sizeDelta = size;

            Image img = btnObj.AddComponent<Image>();
            img.color = Color.white;

            Button btn = btnObj.AddComponent<Button>();
            btn.targetGraphic = img;

            GameObject textObj = new GameObject("Text");
            textObj.transform.SetParent(btnObj.transform, false);
            RectTransform textRect = textObj.AddComponent<RectTransform>();
            textRect.anchorMin = Vector2.zero;
            textRect.anchorMax = Vector2.one;
            textRect.offsetMin = Vector2.zero;
            textRect.offsetMax = Vector2.zero;

            TextMeshProUGUI tmp = textObj.AddComponent<TextMeshProUGUI>();
            tmp.text = text;
            tmp.alignment = TextAlignmentOptions.Center;
            tmp.color = Color.black;
            tmp.fontSize = 24;

            return btn;
        }

        // Helper to create text
        TextMeshProUGUI CreateText(GameObject parent, string name, string content, Vector2 pos, Vector2 size)
        {
            GameObject textObj = new GameObject(name);
            textObj.transform.SetParent(parent.transform, false);
            RectTransform rect = textObj.AddComponent<RectTransform>();
            rect.anchoredPosition = pos;
            rect.sizeDelta = size;

            TextMeshProUGUI tmp = textObj.AddComponent<TextMeshProUGUI>();
            tmp.text = content;
            tmp.alignment = TextAlignmentOptions.Center;
            tmp.color = Color.white;
            tmp.fontSize = 32;

            return tmp;
        }

        // Helper to create input field
        TMP_InputField CreateInputField(GameObject parent, string name, Vector2 pos, Vector2 size)
        {
            GameObject inputObj = new GameObject(name);
            inputObj.transform.SetParent(parent.transform, false);
            RectTransform rect = inputObj.AddComponent<RectTransform>();
            rect.anchoredPosition = pos;
            rect.sizeDelta = size;

            Image img = inputObj.AddComponent<Image>();
            img.color = Color.white;

            TMP_InputField input = inputObj.AddComponent<TMP_InputField>();
            input.targetGraphic = img;

            // Text Area
            GameObject textArea = new GameObject("TextArea");
            textArea.transform.SetParent(inputObj.transform, false);
            RectTransform areaRect = textArea.AddComponent<RectTransform>();
            areaRect.anchorMin = Vector2.zero;
            areaRect.anchorMax = Vector2.one;
            areaRect.offsetMin = new Vector2(10, 10);
            areaRect.offsetMax = new Vector2(-10, -10);

            GameObject textObj = new GameObject("Text");
            textObj.transform.SetParent(textArea.transform, false);
            RectTransform textRect = textObj.AddComponent<RectTransform>();
            textRect.anchorMin = Vector2.zero;
            textRect.anchorMax = Vector2.one;
            textRect.offsetMin = Vector2.zero;
            textRect.offsetMax = Vector2.zero;

            TextMeshProUGUI textComp = textObj.AddComponent<TextMeshProUGUI>();
            textComp.color = Color.black;
            textComp.fontSize = 24;

            input.textViewport = areaRect;
            input.textComponent = textComp;

            return input;
        }

        // 1. Main Menu Panel
        GameObject mainMenuPanel = CreatePanel("MainMenuPanel", true);
        CreateText(mainMenuPanel, "Title", "TANKS MULTIPLAYER", new Vector2(0, 200), new Vector2(600, 100));
        Button createRoomBtn = CreateButton(mainMenuPanel, "CreateRoomBtn", "Create Room", new Vector2(0, 50), new Vector2(300, 80));
        Button joinRoomBtn = CreateButton(mainMenuPanel, "JoinRoomBtn", "Join Room", new Vector2(0, -50), new Vector2(300, 80));

        // 2. Create Room Panel
        GameObject createRoomPanel = CreatePanel("CreateRoomPanel", false);
        CreateText(createRoomPanel, "Title", "ROOM CREATED", new Vector2(0, 200), new Vector2(600, 100));
        TextMeshProUGUI joinCodeText = CreateText(createRoomPanel, "JoinCodeText", "CODE: ...", new Vector2(0, 50), new Vector2(400, 80));
        Button copyCodeBtn = CreateButton(createRoomPanel, "CopyCodeBtn", "Copy Code", new Vector2(0, -50), new Vector2(200, 60));
        Button cancelCreateBtn = CreateButton(createRoomPanel, "CancelBtn", "Cancel", new Vector2(0, -150), new Vector2(200, 60));

        // 3. Join Room Panel
        GameObject joinRoomPanel = CreatePanel("JoinRoomPanel", false);
        CreateText(joinRoomPanel, "Title", "JOIN ROOM", new Vector2(0, 200), new Vector2(600, 100));
        TMP_InputField joinInput = CreateInputField(joinRoomPanel, "JoinCodeInput", new Vector2(0, 50), new Vector2(400, 60));
        Button confirmJoinBtn = CreateButton(joinRoomPanel, "ConfirmBtn", "Join", new Vector2(0, -50), new Vector2(200, 60));
        Button cancelJoinBtn = CreateButton(joinRoomPanel, "CancelBtn", "Cancel", new Vector2(0, -150), new Vector2(200, 60));

        // 4. Waiting Room Panel
        GameObject waitingRoomPanel = CreatePanel("WaitingRoomPanel", false);
        TextMeshProUGUI statusText = CreateText(waitingRoomPanel, "StatusText", "Waiting...", new Vector2(0, 200), new Vector2(600, 100));
        TextMeshProUGUI playerListText = CreateText(waitingRoomPanel, "PlayerListText", "Players: 0", new Vector2(0, 0), new Vector2(600, 300));
        Button leaveRoomBtn = CreateButton(waitingRoomPanel, "LeaveBtn", "Leave Room", new Vector2(0, -200), new Vector2(200, 60));

        // Assign references using Reflection to access private fields
        void SetField(string fieldName, object value)
        {
            FieldInfo field = typeof(NetworkMenu).GetField(fieldName, BindingFlags.NonPublic | BindingFlags.Instance);
            if (field != null)
            {
                field.SetValue(networkMenu, value);
            }
            else
            {
                Debug.LogError($"Field {fieldName} not found in NetworkMenu");
            }
        }

        SetField("mainMenuPanel", mainMenuPanel);
        SetField("createRoomPanel", createRoomPanel);
        SetField("joinRoomPanel", joinRoomPanel);
        SetField("waitingRoomPanel", waitingRoomPanel);

        SetField("createRoomButton", createRoomBtn);
        SetField("joinRoomButton", joinRoomBtn);

        SetField("joinCodeText", joinCodeText);
        SetField("copyJoinCodeButton", copyCodeBtn);
        SetField("cancelCreateButton", cancelCreateBtn);

        SetField("joinCodeInputField", joinInput);
        SetField("confirmJoinButton", confirmJoinBtn);
        SetField("cancelJoinButton", cancelJoinBtn);

        SetField("statusText", statusText);
        SetField("playerListText", playerListText);
        SetField("leaveRoomButton", leaveRoomBtn);

        // Assign RelayManager
        GameObject networkManagerObj = GameObject.Find("NetworkManager");
        if (networkManagerObj != null)
        {
            RelayManager relay = networkManagerObj.GetComponent<RelayManager>();
            SetField("relayManager", relay);
        }

        Debug.Log("Lobby UI Generated Successfully!");
    }
}

