using UnityEngine;
using Unity.Netcode;
using UnityEditor;

public class NetworkConfigurator : MonoBehaviour
{
    public static void ConfigureNetworkManager()
    {
        GameObject networkManagerObj = GameObject.Find("NetworkManager");
        if (networkManagerObj == null)
        {
            Debug.LogError("NetworkManager not found!");
            return;
        }

        NetworkManager networkManager = networkManagerObj.GetComponent<NetworkManager>();
        if (networkManager == null)
        {
            Debug.LogError("NetworkManager component not found!");
            return;
        }

        // Load DefaultNetworkPrefabs
        string assetPath = "Assets/DefaultNetworkPrefabs.asset";
        NetworkPrefabsList prefabsList = AssetDatabase.LoadAssetAtPath<NetworkPrefabsList>(assetPath);

        if (prefabsList != null)
        {
            networkManager.NetworkConfig.NetworkPrefabs.Clear();
            foreach (var prefab in prefabsList.List)
            {
                networkManager.NetworkConfig.NetworkPrefabs.Add(prefab);
            }
            Debug.Log($"Assigned {prefabsList.List.Count} network prefabs to NetworkManager.");
        }
        else
        {
            Debug.LogError($"Could not load NetworkPrefabsList at {assetPath}");
        }

        // Also ensure UnityTransport is set
        var transport = networkManagerObj.GetComponent<Unity.Netcode.Transports.UTP.UnityTransport>();
        if (transport != null)
        {
            networkManager.NetworkConfig.NetworkTransport = transport;
            Debug.Log("Assigned UnityTransport to NetworkManager.");
        }
    }
}

