using UnityEngine;
using Unity.Netcode;
using UnityEditor;
using System.Collections.Generic;

public class NetworkConfigurator : MonoBehaviour
{
    public static void ConfigureNetworkManager()
    {
        GameObject networkManagerObj = GameObject.Find("NetworkManager");
        if (networkManagerObj == null)
        {
            Debug.LogError("NetworkManager not found!");
            return;
        }

        NetworkManager networkManager = networkManagerObj.GetComponent<NetworkManager>();
        if (networkManager == null)
        {
            Debug.LogError("NetworkManager component not found!");
            return;
        }

        // Load DefaultNetworkPrefabs
        string assetPath = "Assets/DefaultNetworkPrefabs.asset";
        NetworkPrefabsList prefabsList = AssetDatabase.LoadAssetAtPath<NetworkPrefabsList>(assetPath);

        if (prefabsList != null)
        {
            // Access via SerializedObject to be safe and handle potential API differences or serialization issues
            SerializedObject so = new SerializedObject(networkManager);
            SerializedProperty networkConfigProp = so.FindProperty("NetworkConfig");
            if (networkConfigProp != null)
            {
                SerializedProperty prefabsProp = networkConfigProp.FindPropertyRelative("Prefabs");
                if (prefabsProp != null)
                {
                    SerializedProperty listsProp = prefabsProp.FindPropertyRelative("NetworkPrefabsLists");
                    if (listsProp != null && listsProp.isArray)
                    {
                        listsProp.ClearArray();
                        listsProp.InsertArrayElementAtIndex(0);
                        listsProp.GetArrayElementAtIndex(0).objectReferenceValue = prefabsList;
                        so.ApplyModifiedProperties();
                        Debug.Log("Assigned DefaultNetworkPrefabs to NetworkManager via SerializedObject.");
                    }
                    else
                    {
                        Debug.LogError("Could not find 'NetworkPrefabsLists' property in 'Prefabs'.");
                    }
                }
                else
                {
                    // Try old 'NetworkPrefabs' property if 'Prefabs' doesn't exist (legacy support)
                    SerializedProperty oldPrefabsProp = networkConfigProp.FindPropertyRelative("NetworkPrefabs");
                    if (oldPrefabsProp != null && oldPrefabsProp.isArray)
                    {
                         // This is a list of NetworkPrefab, not NetworkPrefabsList
                         // We can't easily assign a NetworkPrefabsList here without iterating
                         Debug.LogWarning("Found legacy 'NetworkPrefabs' property. Cannot assign NetworkPrefabsList directly.");
                    }
                    else
                    {
                        Debug.LogError("Could not find 'Prefabs' property in 'NetworkConfig'.");
                    }
                }
            }
            else
            {
                Debug.LogError("Could not find 'NetworkConfig' property on NetworkManager.");
            }
        }
        else
        {
            Debug.LogError($"Could not load NetworkPrefabsList at {assetPath}");
        }

        // Ensure UnityTransport is set
        var transport = networkManagerObj.GetComponent<Unity.Netcode.Transports.UTP.UnityTransport>();
        if (transport != null)
        {
            networkManager.NetworkConfig.NetworkTransport = transport;
            Debug.Log("Assigned UnityTransport to NetworkManager.");
        }
    }
}

