using System.Collections;
using Unity.Netcode;
using UnityEngine;
using TMPro;

namespace Tanks.Complete
{
    /// <summary>
    /// NetworkGameManager wraps GameManager để thêm multiplayer functionality.
    /// Hoạt động như network layer giữa clients và local GameManager logic.
    /// Server authority cho game state, rounds, và scoring.
    /// </summary>
    public class NetworkGameManager : NetworkBehaviour
    {
        [Header("References")]
        public GameManager m_LocalGameManager;  // Reference to local GameManager
        
        [Header("Network State")]
        // Game state synchronized across all clients
        private NetworkVariable<GameManager.GameState> m_NetworkGameState = new NetworkVariable<GameManager.GameState>(
            GameManager.GameState.MainMenu,
            NetworkVariableReadPermission.Everyone,
            NetworkVariableWritePermission.Server
        );
        
        // Current round number synchronized
        private NetworkVariable<int> m_NetworkRoundNumber = new NetworkVariable<int>(
            0,
            NetworkVariableReadPermission.Everyone,
            NetworkVariableWritePermission.Server
        );
        
        // Number of active players
        private NetworkVariable<int> m_NetworkPlayerCount = new NetworkVariable<int>(
            0,
            NetworkVariableReadPermission.Everyone,
            NetworkVariableWritePermission.Server
        );
        
        // Current game phase for synchronization
        public enum GamePhase
        {
            Waiting,
            RoundStarting,
            RoundPlaying,
            RoundEnding,
            GameOver
        }
        
        private NetworkVariable<GamePhase> m_CurrentPhase = new NetworkVariable<GamePhase>(
            GamePhase.Waiting,
            NetworkVariableReadPermission.Everyone,
            NetworkVariableWritePermission.Server
        );
        
        // Track player scores (client ID -> wins)
        private NetworkList<PlayerScore> m_PlayerScores;
        
        // Track player tank selections (client ID -> tank index)
        private NetworkList<PlayerTankSelection> m_PlayerTankSelections;

        public struct PlayerTankSelection : INetworkSerializable, System.IEquatable<PlayerTankSelection>
        {
            public ulong ClientId;
            public int TankIndex;

            public void NetworkSerialize<T>(BufferSerializer<T> serializer) where T : IReaderWriter
            {
                serializer.SerializeValue(ref ClientId);
                serializer.SerializeValue(ref TankIndex);
            }

            public bool Equals(PlayerTankSelection other)
            {
                return ClientId == other.ClientId && TankIndex == other.TankIndex;
            }
        }

        // Structure to hold player score data
        public struct PlayerScore : INetworkSerializable, System.IEquatable<PlayerScore>
        {
            public ulong ClientId;
            public int Wins;
            public Color PlayerColor;
            
            public void NetworkSerialize<T>(BufferSerializer<T> serializer) where T : IReaderWriter
            {
                serializer.SerializeValue(ref ClientId);
                serializer.SerializeValue(ref Wins);
                serializer.SerializeValue(ref PlayerColor);
            }
            
            public bool Equals(PlayerScore other)
            {
                return ClientId == other.ClientId && Wins == other.Wins;
            }
        }
        
        private void Awake()
        {
            // Initialize NetworkList in Awake to avoid memory leaks
            m_PlayerScores = new NetworkList<PlayerScore>();
            m_PlayerTankSelections = new NetworkList<PlayerTankSelection>();
            
            DontDestroyOnLoad(gameObject);
        }
        
        public override void OnNetworkSpawn()
        {
            base.OnNetworkSpawn();
            
            // Find GameManager if not assigned
            if (m_LocalGameManager == null)
            {
                m_LocalGameManager = FindFirstObjectByType<GameManager>();
            }

            NetworkManager.Singleton.SceneManager.OnLoadEventCompleted += OnLoadEventCompleted;

            if (IsServer)
            {
                // Server listens for client connections
                NetworkManager.Singleton.OnClientConnectedCallback += OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback += OnClientDisconnected;
                
                // Subscribe to list changes
                m_PlayerScores.OnListChanged += OnServerScoresChanged;
            }
            
            if (IsClient)
            {
                // Clients subscribe to network variable changes
                m_NetworkGameState.OnValueChanged += OnGameStateChanged;
                m_NetworkRoundNumber.OnValueChanged += OnRoundNumberChanged;
                m_CurrentPhase.OnValueChanged += OnPhaseChanged;
                m_PlayerScores.OnListChanged += OnClientScoresChanged;
            }
        }

        private void OnLoadEventCompleted(string sceneName, UnityEngine.SceneManagement.LoadSceneMode loadSceneMode, System.Collections.Generic.List<ulong> clientsCompleted, System.Collections.Generic.List<ulong> clientsTimedOut)
        {
            if (m_LocalGameManager == null)
            {
                m_LocalGameManager = FindFirstObjectByType<GameManager>();
                Debug.Log($"[NetworkGameManager] Found GameManager in scene {sceneName}: {m_LocalGameManager != null}");
            }
            
            if (IsServer && sceneName == "Main")
            {
                StartNetworkGame();
            }
        }
        
        public override void OnNetworkDespawn()
        {
            base.OnNetworkDespawn();
            
            if (NetworkManager.Singleton != null && NetworkManager.Singleton.SceneManager != null)
            {
                NetworkManager.Singleton.SceneManager.OnLoadEventCompleted -= OnLoadEventCompleted;
            }

            if (IsServer)
            {
                if (NetworkManager.Singleton != null)
                {
                    NetworkManager.Singleton.OnClientConnectedCallback -= OnClientConnected;
                    NetworkManager.Singleton.OnClientDisconnectCallback -= OnClientDisconnected;
                }
            }
        }
        
        #region Server Callbacks
        
        private void OnClientConnected(ulong clientId)
        {
            Debug.Log($"[Server] Client {clientId} connected. Total players: {NetworkManager.Singleton.ConnectedClients.Count}");
            
            // Add player to scores list
            m_PlayerScores.Add(new PlayerScore 
            { 
                ClientId = clientId, 
                Wins = 0,
                PlayerColor = GetPlayerColor(m_PlayerScores.Count)
            });

            // Add default tank selection
            m_PlayerTankSelections.Add(new PlayerTankSelection
            {
                ClientId = clientId,
                TankIndex = (int)clientId % 4 // Default to client ID based index
            });
            
            m_NetworkPlayerCount.Value = NetworkManager.Singleton.ConnectedClients.Count;
            
            // Notify all clients about new player
            NotifyPlayerJoinedClientRpc(clientId);
        }
        
        private void OnClientDisconnected(ulong clientId)
        {
            Debug.Log($"[Server] Client {clientId} disconnected");
            
            // Remove player from scores
            for (int i = 0; i < m_PlayerScores.Count; i++)
            {
                if (m_PlayerScores[i].ClientId == clientId)
                {
                    m_PlayerScores.RemoveAt(i);
                    break;
                }
            }

            // Remove player from selections
            for (int i = 0; i < m_PlayerTankSelections.Count; i++)
            {
                if (m_PlayerTankSelections[i].ClientId == clientId)
                {
                    m_PlayerTankSelections.RemoveAt(i);
                    break;
                }
            }
            
            m_NetworkPlayerCount.Value = NetworkManager.Singleton.ConnectedClients.Count;
            
            // Notify all clients
            NotifyPlayerLeftClientRpc(clientId);
        }
        
        private Color GetPlayerColor(int index)
        {
            Color[] colors = new Color[] 
            { 
                Color.red, 
                Color.blue, 
                Color.green, 
                Color.yellow 
            };
            return colors[index % colors.Length];
        }
        
