        #region Game Logic - Server Only
        
        /// <summary>
        /// Start the networked game (Server only)
        /// </summary>
        public void StartNetworkGame()
        {
            if (!IsServer) return;
            
            Debug.Log("[Server] Starting network game");
            
            m_NetworkGameState.Value = GameManager.GameState.Game;
            m_NetworkRoundNumber.Value = 0;
            m_CurrentPhase.Value = GamePhase.RoundStarting;
            
            // Spawn tanks for all connected players
            SpawnAllTanks();
            
            // Start game loop
            StartCoroutine(NetworkGameLoop());
        }
        
        /// <summary>
        /// Spawn tanks for all connected clients (Server only)
        /// </summary>
        private void SpawnAllTanks()
        {
            if (!IsServer) return;
            
            int playerIndex = 0;
            foreach (var clientId in NetworkManager.Singleton.ConnectedClientsIds)
            {
                SpawnTankForPlayer(clientId, playerIndex);
                playerIndex++;
            }
        }
        
        /// <summary>
        /// Spawn a tank for specific player (Server only)
        /// </summary>
        private void SpawnTankForPlayer(ulong clientId, int spawnIndex)
        {
            if (!IsServer) return;
            
            // Get spawn point from local GameManager
            if (m_LocalGameManager != null && spawnIndex < m_LocalGameManager.m_SpawnPoints.Length)
            {
                var spawnPoint = m_LocalGameManager.m_SpawnPoints[spawnIndex];
                
                // Get the appropriate tank prefab based on selection
                int tankIndex = GetPlayerTankSelection(clientId);
                GameObject tankPrefab = GetTankPrefab(tankIndex);
                
                if (tankPrefab != null)
                {
                    GameObject tankInstance = Instantiate(
                        tankPrefab, 
                        spawnPoint.m_SpawnPoint.position, 
                        spawnPoint.m_SpawnPoint.rotation
                    );
                    
                    NetworkObject netObj = tankInstance.GetComponent<NetworkObject>();
                    if (netObj != null)
                    {
                        // Spawn as player object for ownership
                        netObj.SpawnAsPlayerObject(clientId);
                        
                        Debug.Log($"[Server] Spawned tank for client {clientId} at index {spawnIndex}");
                    }
                }
            }
        }
        
        private GameObject GetTankPrefab(int index)
        {
            if (m_LocalGameManager == null) return null;
            
            switch (index)
            {
                case 0: return m_LocalGameManager.m_Tank1Prefab;
                case 1: return m_LocalGameManager.m_Tank2Prefab;
                case 2: return m_LocalGameManager.m_Tank3Prefab;
                case 3: return m_LocalGameManager.m_Tank4Prefab;
                default: return m_LocalGameManager.m_Tank1Prefab;
            }
        }

        private int GetPlayerTankSelection(ulong clientId)
        {
            foreach (var selection in m_PlayerTankSelections)
            {
                if (selection.ClientId == clientId)
                {
                    return selection.TankIndex;
                }
            }
            return 0;
        }

        [ServerRpc(RequireOwnership = false)]
        public void SetPlayerTankSelectionServerRpc(int tankIndex, ServerRpcParams rpcParams = default)
        {
            ulong clientId = rpcParams.Receive.SenderClientId;
            
            for (int i = 0; i < m_PlayerTankSelections.Count; i++)
            {
                if (m_PlayerTankSelections[i].ClientId == clientId)
                {
                    var selection = m_PlayerTankSelections[i];
                    selection.TankIndex = tankIndex;
                    m_PlayerTankSelections[i] = selection;
                    return;
                }
            }
        }
        
        /// <summary>
        /// Main game loop for networked game (Server only)
        /// </summary>
        private IEnumerator NetworkGameLoop()
        {
            if (!IsServer) yield break;
            
            while (m_NetworkGameState.Value == GameManager.GameState.Game)
            {
                // Round Starting Phase
                yield return StartCoroutine(NetworkRoundStarting());
                
                // Round Playing Phase
                yield return StartCoroutine(NetworkRoundPlaying());
                
                // Round Ending Phase
                yield return StartCoroutine(NetworkRoundEnding());
                
                // Check for game winner
                ulong gameWinner = CheckGameWinner();
                if (gameWinner != 0)
                {
                    m_CurrentPhase.Value = GamePhase.GameOver;
                    UpdateTitleTextClientRpc($"PLAYER {gameWinner} WINS THE GAME!");
                    yield break;
                }
            }
        }
        
        private IEnumerator NetworkRoundStarting()
        {
            m_CurrentPhase.Value = GamePhase.RoundStarting;
            m_NetworkRoundNumber.Value++;
            
            // Reset all tanks to spawn positions
            ResetAllTanks();
            
            // Notify clients
            UpdateTitleTextClientRpc($"ROUND {m_NetworkRoundNumber.Value}");
            StartRoundClientRpc(m_NetworkRoundNumber.Value);
            
            // Wait for start delay
            yield return new WaitForSeconds(m_LocalGameManager != null ? m_LocalGameManager.m_StartDelay : 3f);
        }
        
        private IEnumerator NetworkRoundPlaying()
        {
            m_CurrentPhase.Value = GamePhase.RoundPlaying;
            
            // Clear UI
            UpdateTitleTextClientRpc("");
            
            // Enable tank controls
            EnableTankControlsClientRpc();
            
            // Wait until only one tank left
            while (!CheckOneTankLeft())
            {
                yield return null;
            }
        }
        
        private IEnumerator NetworkRoundEnding()
        {
            m_CurrentPhase.Value = GamePhase.RoundEnding;
            
            // Disable tank controls
            DisableTankControlsClientRpc();
            
            // Get round winner and update scores
            ulong winnerClientId = GetRoundWinner();
            if (winnerClientId != 0)
            {
                UpdatePlayerScore(winnerClientId);
            }
            
            // Generate and send end message
            string endMessage = GenerateEndMessage(winnerClientId);
            EndRoundClientRpc(winnerClientId, endMessage);
            
            // Wait for end delay
            yield return new WaitForSeconds(m_LocalGameManager != null ? m_LocalGameManager.m_EndDelay : 3f);
        }
        
        private bool CheckOneTankLeft()
        {
            // Count active tanks
            int activeTanks = 0;
            foreach (var netObj in FindObjectsByType<NetworkObject>(FindObjectsSortMode.None))
            {
                if (netObj.CompareTag("Player") && netObj.IsSpawned)
                {
                    var health = netObj.GetComponent<TankHealth>();
                    if (health != null && health.gameObject.activeSelf)
                    {
                        activeTanks++;
                    }
                }
            }
            
            return activeTanks <= 1;
        }
        
        private void CheckRoundEnd()
        {
            // This is called when a tank dies
            // The coroutine will handle checking OneTankLeft
        }
        
        private ulong GetRoundWinner()
        {
            // Find the last active tank
            foreach (var netObj in FindObjectsByType<NetworkObject>(FindObjectsSortMode.None))
            {
                if (netObj.CompareTag("Player") && netObj.IsSpawned)
                {
                    var health = netObj.GetComponent<TankHealth>();
                    if (health != null && health.gameObject.activeSelf)
                    {
                        return netObj.OwnerClientId;
                    }
                }
            }
            
            return 0; // Draw
        }
        
        private void UpdatePlayerScore(ulong clientId)
        {
            for (int i = 0; i < m_PlayerScores.Count; i++)
            {
                if (m_PlayerScores[i].ClientId == clientId)
                {
                    var score = m_PlayerScores[i];
                    score.Wins++;
                    m_PlayerScores[i] = score;
                    break;
                }
            }
        }
        
        private ulong CheckGameWinner()
        {
            int numRoundsToWin = m_LocalGameManager != null ? m_LocalGameManager.m_NumRoundsToWin : 5;
            
            foreach (var score in m_PlayerScores)
            {
                if (score.Wins >= numRoundsToWin)
                {
                    return score.ClientId;
                }
            }
            
            return 0;
        }
        
        private string GenerateEndMessage(ulong winnerClientId)
        {
            string message = winnerClientId == 0 ? "DRAW!" : $"PLAYER {winnerClientId} WINS THE ROUND!";
            message += "\n\n\n\n";
            
            foreach (var score in m_PlayerScores)
            {
                message += $"PLAYER {score.ClientId}: {score.Wins} WINS\n";
            }
            
            return message;
        }
        
        /// <summary>
        /// Reset all tanks to their spawn positions (Server only).
        /// Called at the start of each round.
        /// </summary>
        private void ResetAllTanks()
        {
            if (!IsServer)
                return;

            int spawnIndex = 0;
            
            // Find all spawned player tanks
            foreach (var netObj in FindObjectsByType<NetworkObject>(FindObjectsSortMode.None))
            {
                if (netObj.CompareTag("Player") && netObj.IsSpawned)
                {
                    // Get spawn point for this tank
                    if (m_LocalGameManager != null && spawnIndex < m_LocalGameManager.m_SpawnPoints.Length)
                    {
                        var spawnPoint = m_LocalGameManager.m_SpawnPoints[spawnIndex];
                        
                        // Reset position and rotation
                        netObj.transform.position = spawnPoint.m_SpawnPoint.position;
                        netObj.transform.rotation = spawnPoint.m_SpawnPoint.rotation;
                        
                        // Reset tank health
                        TankHealth health = netObj.GetComponent<TankHealth>();
                        if (health != null)
                        {
                            health.gameObject.SetActive(true);
                            // Health will be reset via OnEnable -> NetworkVariable
                        }
                        
                        // Reset tank movement (velocity, etc.)
                        TankMovement movement = netObj.GetComponent<TankMovement>();
                        if (movement != null && movement.Rigidbody != null)
                        {
                            movement.Rigidbody.linearVelocity = Vector3.zero;
                            movement.Rigidbody.angularVelocity = Vector3.zero;
                        }
                        
                        spawnIndex++;
                    }
                }
            }
            
            Debug.Log($"[NetworkGameManager] Reset {spawnIndex} tanks to spawn positions");
        }
        
        #endregion
    }
}

