using UnityEngine;
using Tanks.Complete;

public class SpawnPointChecker : MonoBehaviour
{
    public static void CheckSpawnPoints()
    {
        GameManager gm = GameObject.FindFirstObjectByType<GameManager>();
        if (gm == null)
        {
            Debug.LogError("GameManager not found!");
            return;
        }

        if (gm.m_SpawnPoints == null)
        {
            Debug.LogError("m_SpawnPoints array is null!");
            return;
        }

        Debug.Log($"Found {gm.m_SpawnPoints.Length} spawn points.");
        for (int i = 0; i < gm.m_SpawnPoints.Length; i++)
        {
            var sp = gm.m_SpawnPoints[i];
            if (sp == null)
            {
                Debug.LogError($"Spawn point entry {i} is null.");
            }
            else if (sp.m_SpawnPoint == null)
            {
                Debug.LogError($"Spawn point transform at index {i} is null.");
            }
            else
            {
                Debug.Log($"Spawn point {i}: {sp.m_SpawnPoint.name} at {sp.m_SpawnPoint.position}");
            }
        }
    }
}

