using System;
using System.Threading.Tasks;
using Unity.Netcode;
using Unity.Netcode.Transports.UTP;
using Unity.Services.Authentication;
using Unity.Services.Core;
using Unity.Services.Relay;
using Unity.Services.Relay.Models;
using UnityEngine;

/// <summary>
/// Manages Unity Relay connections for multiplayer gameplay.
/// Provides methods to create and join rooms via join codes.
/// </summary>
public class RelayManager : MonoBehaviour
{
    [Header("Configuration")]
    [SerializeField] private int maxPlayers = 4;
    [SerializeField] private bool debugMode = true;
    
    // Events
    public event Action<string> OnRoomCreated;
    public event Action<bool> OnRoomJoined;
    public event Action<string> OnError;
    
    // Connection state
    private bool isInitialized = false;
    private string currentJoinCode = string.Empty;

    #region Unity Lifecycle

    private void Awake()
    {
        // Persist across scenes if needed
        DontDestroyOnLoad(gameObject);
    }

    #endregion

    #region Unity Services Initialization

    /// <summary>
    /// Initializes Unity Services and authenticates anonymously.
    /// Must be called before any Relay operations.
    /// </summary>
    public async Task<bool> InitializeUnityServices()
    {
        if (isInitialized)
        {
            LogDebug("Unity Services already initialized.");
            return true;
        }

        try
        {
            LogDebug("Initializing Unity Services...");
            
            // Initialize the Unity Services engine
            await UnityServices.InitializeAsync();
            
            // Authenticate anonymously if not signed in
            if (!AuthenticationService.Instance.IsSignedIn)
            {
                LogDebug("Signing in anonymously...");
                await AuthenticationService.Instance.SignInAnonymouslyAsync();
                LogDebug($"Signed in with Player ID: {AuthenticationService.Instance.PlayerId}");
            }
            
            isInitialized = true;
            LogDebug("Unity Services initialized successfully.");
            return true;
        }
        catch (Exception ex)
        {
            LogError($"Failed to initialize Unity Services: {ex.Message}");
            OnError?.Invoke($"Initialization failed: {ex.Message}");
            return false;
        }
    }

    #endregion

    #region Host Operations (Create Room)

    /// <summary>
    /// Creates a new Relay allocation and starts the host.
    /// Returns the join code that clients can use to join.
    /// </summary>
    public async Task<string> CreateRoom()
    {
        try
        {
            // Ensure Unity Services is initialized
            if (!await EnsureInitialized())
            {
                return null;
            }

            LogDebug($"Creating Relay allocation for {maxPlayers} players...");

            // Create a Relay allocation for (maxPlayers - 1) connections
            // -1 because host doesn't count as a connection
            Allocation allocation = await RelayService.Instance.CreateAllocationAsync(maxPlayers - 1);
            
            LogDebug($"Relay allocation created. Allocation ID: {allocation.AllocationId}");

            // Get the join code for this allocation
            string joinCode = await RelayService.Instance.GetJoinCodeAsync(allocation.AllocationId);
            currentJoinCode = joinCode;
            
            LogDebug($"Join code generated: {joinCode}");

            // Configure Unity Transport with Relay server data
            var transport = NetworkManager.Singleton.GetComponent<UnityTransport>();
            if (transport == null)
            {
                LogError("UnityTransport component not found on NetworkManager!");
                OnError?.Invoke("Transport component missing.");
                return null;
            }

            // Set Relay server data with DTLS connection type
            transport.SetHostRelayData(
                allocation.RelayServer.IpV4,
                (ushort)allocation.RelayServer.Port,
                allocation.AllocationIdBytes,
                allocation.Key,
                allocation.ConnectionData,
                isSecure: true
            );
            
            LogDebug("Unity Transport configured with Relay server data.");

            // Start as host
            if (!NetworkManager.Singleton.StartHost())
            {
                LogError("Failed to start as host!");
                OnError?.Invoke("Failed to start host.");
                return null;
            }

            LogDebug($"Host started successfully! Join code: {joinCode}");
            OnRoomCreated?.Invoke(joinCode);
            
            return joinCode;
        }
        catch (RelayServiceException ex)
        {
            LogError($"Relay Service Error: {ex.Message} (Reason: {ex.Reason})");
            OnError?.Invoke($"Relay error: {ex.Reason}");
            return null;
        }
        catch (Exception ex)
        {
            LogError($"Failed to create room: {ex.Message}");
            OnError?.Invoke($"Room creation failed: {ex.Message}");
            return null;
        }
    }

    #endregion

    #region Client Operations (Join Room)

    /// <summary>
    /// Joins an existing Relay allocation using a join code.
    /// Returns true if successfully joined.
    /// </summary>
    public async Task<bool> JoinRoom(string joinCode)
    {
        if (string.IsNullOrEmpty(joinCode))
        {
            LogError("Join code cannot be empty!");
            OnError?.Invoke("Invalid join code.");
            return false;
        }

        try
        {
            // Ensure Unity Services is initialized
            if (!await EnsureInitialized())
            {
                return false;
            }

            LogDebug($"Joining Relay allocation with code: {joinCode}");

            // Join the Relay allocation using the provided join code
            JoinAllocation joinAllocation = await RelayService.Instance.JoinAllocationAsync(joinCode);
            
            LogDebug($"Successfully joined allocation. Allocation ID: {joinAllocation.AllocationId}");

            // Configure Unity Transport with Relay server data
            var transport = NetworkManager.Singleton.GetComponent<UnityTransport>();
            if (transport == null)
            {
                LogError("UnityTransport component not found on NetworkManager!");
                OnError?.Invoke("Transport component missing.");
                return false;
            }

            // Set Relay server data with DTLS connection type
            transport.SetClientRelayData(
                joinAllocation.RelayServer.IpV4,
                (ushort)joinAllocation.RelayServer.Port,
                joinAllocation.AllocationIdBytes,
                joinAllocation.Key,
                joinAllocation.ConnectionData,
                joinAllocation.HostConnectionData,
                isSecure: true
            );
            
            LogDebug("Unity Transport configured with Relay server data.");

            // Start as client
            if (!NetworkManager.Singleton.StartClient())
            {
                LogError("Failed to start as client!");
                OnError?.Invoke("Failed to connect.");
                return false;
            }

            currentJoinCode = joinCode;
            LogDebug("Client started successfully!");
            OnRoomJoined?.Invoke(true);
            
            return true;
        }
        catch (RelayServiceException ex)
        {
            LogError($"Relay Service Error: {ex.Message} (Reason: {ex.Reason})");
            OnError?.Invoke($"Join failed: {ex.Reason}");
            OnRoomJoined?.Invoke(false);
            return false;
        }
        catch (Exception ex)
        {
            LogError($"Failed to join room: {ex.Message}");
            OnError?.Invoke($"Join failed: {ex.Message}");
            OnRoomJoined?.Invoke(false);
            return false;
        }
    }

    #endregion

    #region Disconnection

    /// <summary>
    /// Disconnects from the current Relay session and shuts down NetworkManager.
    /// </summary>
    public void LeaveRoom()
    {
        try
        {
            if (NetworkManager.Singleton != null && NetworkManager.Singleton.IsListening)
            {
                LogDebug("Shutting down NetworkManager...");
                NetworkManager.Singleton.Shutdown();
            }

            currentJoinCode = string.Empty;
            LogDebug("Left room successfully.");
        }
        catch (Exception ex)
        {
            LogError($"Error leaving room: {ex.Message}");
        }
    }

    #endregion

    #region Helper Methods

    /// <summary>
    /// Ensures Unity Services is initialized before performing operations.
    /// </summary>
    private async Task<bool> EnsureInitialized()
    {
        if (!isInitialized)
        {
            return await InitializeUnityServices();
        }
        return true;
    }

    /// <summary>
    /// Gets the current join code (if host).
    /// </summary>
    public string GetCurrentJoinCode()
    {
        return currentJoinCode;
    }

    /// <summary>
    /// Checks if currently connected to a Relay session.
    /// </summary>
    public bool IsConnected()
    {
        return NetworkManager.Singleton != null && NetworkManager.Singleton.IsListening;
    }

    /// <summary>
    /// Checks if this client is the host.
    /// </summary>
    public bool IsHost()
    {
        return NetworkManager.Singleton != null && NetworkManager.Singleton.IsHost;
    }

    #endregion

    #region Debug Logging

    private void LogDebug(string message)
    {
        if (debugMode)
        {
            Debug.Log($"[RelayManager] {message}");
        }
    }

    private void LogError(string message)
    {
        Debug.LogError($"[RelayManager] {message}");
    }

    #endregion

    #region Cleanup

    private void OnDestroy()
    {
        LeaveRoom();
    }

    #endregion
}

using System;
using TMPro;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.UI;

public class NetworkMenu : MonoBehaviour
{
    [Header("UI Panels")]
        [SerializeField] private GameObject mainMenuPanel;
        [SerializeField] private GameObject createRoomPanel;
        [SerializeField] private GameObject joinRoomPanel;
        [SerializeField] private GameObject waitingRoomPanel;

        [Header("Main Menu Buttons")]
        [SerializeField] private Button createRoomButton;
        [SerializeField] private Button joinRoomButton;

        [Header("Create Room UI")]
        [SerializeField] private TextMeshProUGUI joinCodeText;
        [SerializeField] private Button copyJoinCodeButton;
        [SerializeField] private Button cancelCreateButton;

        [Header("Join Room UI")]
        [SerializeField] private TMP_InputField joinCodeInputField;
        [SerializeField] private Button confirmJoinButton;
        [SerializeField] private Button cancelJoinButton;

        [Header("Waiting Room UI")]
        [SerializeField] private TextMeshProUGUI statusText;
        [SerializeField] private TextMeshProUGUI playerListText;
        [SerializeField] private TMP_Dropdown tankSelectionDropdown;
        [SerializeField] private Button startGameButton;
        [SerializeField] private Button leaveRoomButton;

        [Header("Game Settings")]
        [SerializeField] private string gameSceneName = "Main";

        [Header("References")]
        [SerializeField] private RelayManager relayManager;

        private void Awake()
        {
            // Find RelayManager if not assigned
            if (relayManager == null)
            {
                relayManager = FindFirstObjectByType<RelayManager>();
                if (relayManager == null)
                {
                    Debug.LogError("[NetworkMenu] RelayManager not found in scene!");
                }
            }

            SetupButtonListeners();
            ShowMainMenu();
        }

        private void OnEnable()
        {
            if (relayManager != null)
            {
                relayManager.OnRoomCreated += HandleRoomCreated;
                relayManager.OnRoomJoined += HandleRoomJoined;
                relayManager.OnError += HandleError;
            }

            if (NetworkManager.Singleton != null)
            {
                NetworkManager.Singleton.OnClientConnectedCallback += OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback += OnClientDisconnected;
            }
        }

        private void OnDisable()
        {
            if (relayManager != null)
            {
                relayManager.OnRoomCreated -= HandleRoomCreated;
                relayManager.OnRoomJoined -= HandleRoomJoined;
                relayManager.OnError -= HandleError;
            }

            if (NetworkManager.Singleton != null)
            {
                NetworkManager.Singleton.OnClientConnectedCallback -= OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback -= OnClientDisconnected;
            }
        }

        #region Button Setup

        private void SetupButtonListeners()
        {
            // Main menu buttons
            if (createRoomButton != null)
                createRoomButton.onClick.AddListener(OnCreateRoomClicked);
            
            if (joinRoomButton != null)
                joinRoomButton.onClick.AddListener(OnJoinRoomClicked);

            // Create room buttons
            if (copyJoinCodeButton != null)
                copyJoinCodeButton.onClick.AddListener(OnCopyJoinCodeClicked);
            
            if (cancelCreateButton != null)
                cancelCreateButton.onClick.AddListener(OnCancelCreateClicked);

            // Join room buttons
            if (confirmJoinButton != null)
                confirmJoinButton.onClick.AddListener(OnConfirmJoinClicked);
            
            if (cancelJoinButton != null)
                cancelJoinButton.onClick.AddListener(OnCancelJoinClicked);

            // Waiting room buttons
            if (leaveRoomButton != null)
                leaveRoomButton.onClick.AddListener(OnLeaveRoomClicked);
            
            if (startGameButton != null)
                startGameButton.onClick.AddListener(OnStartGameClicked);
            
            if (tankSelectionDropdown != null)
                tankSelectionDropdown.onValueChanged.AddListener(OnTankSelectionChanged);
        }

        #endregion

        #region Button Handlers

        private async void OnCreateRoomClicked()
        {
            Debug.Log("[NetworkMenu] Create Room button clicked");
            
            if (relayManager == null)
            {
                Debug.LogError("[NetworkMenu] RelayManager is not assigned!");
                return;
            }

            // Show waiting state
            ShowCreateRoomPanel();
            UpdateJoinCodeText("Creating room...");

            // Create room via Relay
            string joinCode = await relayManager.CreateRoom();

            if (!string.IsNullOrEmpty(joinCode))
            {
                UpdateJoinCodeText(joinCode);
                Debug.Log($"[NetworkMenu] Room created with code: {joinCode}");
            }
            else
            {
                ShowMainMenu();
                Debug.LogError("[NetworkMenu] Failed to create room");
            }
        }

        private void OnJoinRoomClicked()
        {
            Debug.Log("[NetworkMenu] Join Room button clicked");
            ShowJoinRoomPanel();
        }

        private async void OnConfirmJoinClicked()
        {
            if (relayManager == null)
            {
                Debug.LogError("[NetworkMenu] RelayManager is not assigned!");
                return;
            }

            string joinCode = joinCodeInputField.text.Trim().ToUpper();
            
            if (string.IsNullOrEmpty(joinCode))
            {
                Debug.LogWarning("[NetworkMenu] Join code is empty");
                return;
            }

            Debug.Log($"[NetworkMenu] Attempting to join room with code: {joinCode}");
            
            // Show waiting state
            ShowWaitingRoom("Joining room...", "");
            
            // Join room via Relay
            bool success = await relayManager.JoinRoom(joinCode);

            if (success)
            {
                UpdateStatusText("Connected! Waiting for game to start...");
                Debug.Log("[NetworkMenu] Successfully joined room");
            }
            else
            {
                ShowJoinRoomPanel();
                Debug.LogError("[NetworkMenu] Failed to join room");
            }
        }

        private void OnCopyJoinCodeClicked()
        {
            if (relayManager != null)
            {
                string joinCode = relayManager.GetCurrentJoinCode();
                if (!string.IsNullOrEmpty(joinCode))
                {
                    GUIUtility.systemCopyBuffer = joinCode;
                    Debug.Log($"[NetworkMenu] Join code copied to clipboard: {joinCode}");
                }
            }
        }

        private void OnCancelCreateClicked()
        {
            if (relayManager != null)
            {
                relayManager.LeaveRoom();
            }
            ShowMainMenu();
        }

        private void OnCancelJoinClicked()
        {
            ShowMainMenu();
        }

        private void OnLeaveRoomClicked()
        {
            if (relayManager != null)
            {
                relayManager.LeaveRoom();
            }
            ShowMainMenu();
        }

        private void OnStartGameClicked()
        {
            if (NetworkManager.Singleton != null && NetworkManager.Singleton.IsHost)
            {
                Debug.Log($"[NetworkMenu] Starting game, loading scene: {gameSceneName}");
                NetworkManager.Singleton.SceneManager.LoadScene(gameSceneName, UnityEngine.SceneManagement.LoadSceneMode.Single);
            }
        }

        private void OnTankSelectionChanged(int index)
        {
            if (NetworkManager.Singleton != null && NetworkManager.Singleton.IsClient)
            {
                var networkGameManager = NetworkManager.Singleton.GetComponent<Tanks.Complete.NetworkGameManager>();
                if (networkGameManager != null)
                {
                    networkGameManager.SetPlayerTankSelectionRpc(index);
                }
            }
        }

        #endregion

        #region Relay Event Handlers

        private void HandleRoomCreated(string joinCode)
        {
            Debug.Log($"[NetworkMenu] Room created event: {joinCode}");
            ShowWaitingRoom($"Room Created!\nJoin Code: {joinCode}", "Waiting for players...");
        }

        private void HandleRoomJoined(bool success)
        {
            if (success)
            {
                Debug.Log("[NetworkMenu] Successfully joined room");
                ShowWaitingRoom("Connected!", "Waiting for game to start...");
            }
            else
            {
                Debug.LogError("[NetworkMenu] Failed to join room");
                ShowJoinRoomPanel();
            }
        }

        private void HandleError(string errorMessage)
        {
            Debug.LogError($"[NetworkMenu] Relay error: {errorMessage}");
            // Could show error popup here
            ShowMainMenu();
        }

        #endregion

        #region Network Callbacks

        private void OnClientConnected(ulong clientId)
        {
            Debug.Log($"[NetworkMenu] Client connected: {clientId}");
            UpdatePlayerList();
        }

        private void OnClientDisconnected(ulong clientId)
        {
            Debug.Log($"[NetworkMenu] Client disconnected: {clientId}");
            
            // If we disconnected, return to main menu
            if (NetworkManager.Singleton != null && clientId == NetworkManager.Singleton.LocalClientId)
            {
                ShowMainMenu();
            }
            else
            {
                UpdatePlayerList();
            }
        }

        #endregion

        #region UI Panel Management

        private void ShowMainMenu()
        {
            SetPanelActive(mainMenuPanel, true);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, false);
        }

        private void ShowCreateRoomPanel()
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, true);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, false);
        }

        private void ShowJoinRoomPanel()
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, true);
            SetPanelActive(waitingRoomPanel, false);
            
            if (joinCodeInputField != null)
            {
                joinCodeInputField.text = "";
            }
        }

        private void ShowWaitingRoom(string status, string playerInfo)
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, true);
            
            UpdateStatusText(status);
            UpdatePlayerListText(playerInfo);
        }

        private void SetPanelActive(GameObject panel, bool active)
        {
            if (panel != null)
            {
                panel.SetActive(active);
            }
        }

        #endregion

        #region UI Updates

        private void UpdateJoinCodeText(string code)
        {
            if (joinCodeText != null)
            {
                joinCodeText.text = code;
            }
        }

        private void UpdateStatusText(string status)
        {
            if (statusText != null)
            {
                statusText.text = status;
            }
        }

        private void UpdatePlayerListText(string playerInfo)
        {
            if (playerListText != null)
            {
                playerListText.text = playerInfo;
            }
        }

        private void UpdatePlayerList()
        {
            if (NetworkManager.Singleton == null || !NetworkManager.Singleton.IsListening)
            {
                UpdatePlayerListText("Not connected");
                if (startGameButton != null) startGameButton.gameObject.SetActive(false);
                return;
            }

            int connectedPlayers = NetworkManager.Singleton.ConnectedClientsList.Count;
            string playerText = $"Players: {connectedPlayers}";
            
            bool isHost = false;
            if (relayManager != null && relayManager.IsHost())
            {
                playerText += " (You are Host)";
                isHost = true;
            }
            
            UpdatePlayerListText(playerText);
            
            if (startGameButton != null)
            {
                startGameButton.gameObject.SetActive(isHost);
            }
        }

        #endregion

        #region Legacy Support (for backwards compatibility)

        // Keep old methods for scenes that might reference them
        [Obsolete("Use Create/Join Room buttons instead")]
        private void Hide()
        {
            gameObject.SetActive(false);
        }

        #endregion
    }

