using UnityEngine;
using Unity.Netcode;
using UnityEditor;

public class NetworkConfigChecker : MonoBehaviour
{
    public static void CheckSceneManagement()
    {
        GameObject networkManagerObj = GameObject.Find("NetworkManager");
        if (networkManagerObj == null)
        {
            Debug.LogError("NetworkManager not found!");
            return;
        }

        NetworkManager networkManager = networkManagerObj.GetComponent<NetworkManager>();
        if (networkManager == null)
        {
            Debug.LogError("NetworkManager component not found!");
            return;
        }

        // Check EnableSceneManagement via SerializedObject
        SerializedObject so = new SerializedObject(networkManager);
        SerializedProperty networkConfigProp = so.FindProperty("NetworkConfig");
        if (networkConfigProp != null)
        {
            SerializedProperty enableSceneManagementProp = networkConfigProp.FindPropertyRelative("EnableSceneManagement");
            if (enableSceneManagementProp != null)
            {
                Debug.Log($"EnableSceneManagement is currently: {enableSceneManagementProp.boolValue}");
                if (!enableSceneManagementProp.boolValue)
                {
                    enableSceneManagementProp.boolValue = true;
                    so.ApplyModifiedProperties();
                    Debug.Log("EnableSceneManagement has been set to TRUE.");
                }
            }
            else
            {
                Debug.LogError("Could not find 'EnableSceneManagement' property.");
            }
        }
        else
        {
            Debug.LogError("Could not find 'NetworkConfig' property.");
        }
    }
}

