                serializer.SerializeValue(ref TankIndex);
            }

            public bool Equals(PlayerTankSelection other)
            {
                return ClientId == other.ClientId && TankIndex == other.TankIndex;
            }
        }

        // Structure to hold player score data
        public struct PlayerScore : INetworkSerializable, System.IEquatable<PlayerScore>
        {
            public ulong ClientId;
            public int Wins;
            public Color PlayerColor;
            
            public void NetworkSerialize<T>(BufferSerializer<T> serializer) where T : IReaderWriter
            {
                serializer.SerializeValue(ref ClientId);
                serializer.SerializeValue(ref Wins);
                serializer.SerializeValue(ref PlayerColor);
            }
            
            public bool Equals(PlayerScore other)
            {
                return ClientId == other.ClientId && Wins == other.Wins;
            }
        }
        
        private void Awake()
        {
            // Initialize NetworkList in Awake to avoid memory leaks
            m_PlayerScores = new NetworkList<PlayerScore>();
            m_PlayerTankSelections = new NetworkList<PlayerTankSelection>();
            
            DontDestroyOnLoad(gameObject);
        }
        
        public override void OnNetworkSpawn()
        {
            base.OnNetworkSpawn();
            
            // Find GameManager if not assigned
            if (m_LocalGameManager == null)
            {
                m_LocalGameManager = FindFirstObjectByType<GameManager>();
            }

            NetworkManager.Singleton.SceneManager.OnLoadEventCompleted += OnLoadEventCompleted;

            if (IsServer)
            {
                // Server listens for client connections
                NetworkManager.Singleton.OnClientConnectedCallback += OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback += OnClientDisconnected;
                
                // Subscribe to list changes
                m_PlayerScores.OnListChanged += OnServerScoresChanged;
            }
            
            if (IsClient)
            {
                // Clients subscribe to network variable changes
                m_NetworkGameState.OnValueChanged += OnGameStateChanged;
                m_NetworkRoundNumber.OnValueChanged += OnRoundNumberChanged;
                m_CurrentPhase.OnValueChanged += OnPhaseChanged;
                m_PlayerScores.OnListChanged += OnClientScoresChanged;
            }
        }

        private void OnLoadEventCompleted(string sceneName, UnityEngine.SceneManagement.LoadSceneMode loadSceneMode, System.Collections.Generic.List<ulong> clientsCompleted, System.Collections.Generic.List<ulong> clientsTimedOut)
        {
            if (m_LocalGameManager == null)
            {
                m_LocalGameManager = FindFirstObjectByType<GameManager>();
                Debug.Log($"[NetworkGameManager] Found GameManager in scene {sceneName}: {m_LocalGameManager != null}");
