        public void OnTankDeathServerRpc(ulong tankOwnerClientId, ServerRpcParams rpcParams = default)
        {
            Debug.Log($"[Server] Tank owned by client {tankOwnerClientId} died");
            
            // Server will check win conditions
            CheckRoundEnd();
