using System;
using TMPro;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.UI;

public class NetworkMenu : MonoBehaviour
{
    [Header("UI Panels")]
        [SerializeField] private GameObject mainMenuPanel;
        [SerializeField] private GameObject createRoomPanel;
        [SerializeField] private GameObject joinRoomPanel;
        [SerializeField] private GameObject waitingRoomPanel;

        [Header("Main Menu Buttons")]
        [SerializeField] private Button createRoomButton;
        [SerializeField] private Button joinRoomButton;

        [Header("Create Room UI")]
        [SerializeField] private TextMeshProUGUI joinCodeText;
        [SerializeField] private Button copyJoinCodeButton;
        [SerializeField] private Button cancelCreateButton;

        [Header("Join Room UI")]
        [SerializeField] private TMP_InputField joinCodeInputField;
        [SerializeField] private Button confirmJoinButton;
        [SerializeField] private Button cancelJoinButton;

        [Header("Waiting Room UI")]
        [SerializeField] private TextMeshProUGUI statusText;
        [SerializeField] private TextMeshProUGUI playerListText;
        [SerializeField] private TMP_Dropdown tankSelectionDropdown;
        [SerializeField] private Button startGameButton;
        [SerializeField] private Button leaveRoomButton;

        [Header("Game Settings")]
        [SerializeField] private string gameSceneName = "Main";

        [Header("References")]
        [SerializeField] private RelayManager relayManager;

        private void Awake()
        {
            // Find RelayManager if not assigned
            if (relayManager == null)
            {
                relayManager = FindFirstObjectByType<RelayManager>();
                if (relayManager == null)
                {
                    Debug.LogError("[NetworkMenu] RelayManager not found in scene!");
                }
            }

            SetupButtonListeners();
            ShowMainMenu();
        }

        private void OnEnable()
        {
            if (relayManager != null)
            {
                relayManager.OnRoomCreated += HandleRoomCreated;
                relayManager.OnRoomJoined += HandleRoomJoined;
                relayManager.OnError += HandleError;
            }

            if (NetworkManager.Singleton != null)
            {
                NetworkManager.Singleton.OnClientConnectedCallback += OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback += OnClientDisconnected;
            }
        }

        private void OnDisable()
        {
            if (relayManager != null)
            {
                relayManager.OnRoomCreated -= HandleRoomCreated;
                relayManager.OnRoomJoined -= HandleRoomJoined;
                relayManager.OnError -= HandleError;
            }

            if (NetworkManager.Singleton != null)
            {
                NetworkManager.Singleton.OnClientConnectedCallback -= OnClientConnected;
                NetworkManager.Singleton.OnClientDisconnectCallback -= OnClientDisconnected;
            }
        }

        #region Button Setup

        private void SetupButtonListeners()
        {
            // Main menu buttons
            if (createRoomButton != null)
                createRoomButton.onClick.AddListener(OnCreateRoomClicked);
            
            if (joinRoomButton != null)
                joinRoomButton.onClick.AddListener(OnJoinRoomClicked);

            // Create room buttons
            if (copyJoinCodeButton != null)
                copyJoinCodeButton.onClick.AddListener(OnCopyJoinCodeClicked);
            
            if (cancelCreateButton != null)
                cancelCreateButton.onClick.AddListener(OnCancelCreateClicked);

            // Join room buttons
            if (confirmJoinButton != null)
                confirmJoinButton.onClick.AddListener(OnConfirmJoinClicked);
            
            if (cancelJoinButton != null)
                cancelJoinButton.onClick.AddListener(OnCancelJoinClicked);

            // Waiting room buttons
            if (leaveRoomButton != null)
                leaveRoomButton.onClick.AddListener(OnLeaveRoomClicked);
            
            if (startGameButton != null)
                startGameButton.onClick.AddListener(OnStartGameClicked);
            
            if (tankSelectionDropdown != null)
                tankSelectionDropdown.onValueChanged.AddListener(OnTankSelectionChanged);
        }

        #endregion

        #region Button Handlers

        private async void OnCreateRoomClicked()
        {
            Debug.Log("[NetworkMenu] Create Room button clicked");
            
            if (relayManager == null)
            {
                Debug.LogError("[NetworkMenu] RelayManager is not assigned!");
                return;
            }

            // Show waiting state
            ShowCreateRoomPanel();
            UpdateJoinCodeText("Creating room...");

            // Create room via Relay
            string joinCode = await relayManager.CreateRoom();

            if (!string.IsNullOrEmpty(joinCode))
            {
                UpdateJoinCodeText(joinCode);
                Debug.Log($"[NetworkMenu] Room created with code: {joinCode}");
            }
            else
            {
                ShowMainMenu();
                Debug.LogError("[NetworkMenu] Failed to create room");
            }
        }

        private void OnJoinRoomClicked()
        {
            Debug.Log("[NetworkMenu] Join Room button clicked");
            ShowJoinRoomPanel();
        }

        private async void OnConfirmJoinClicked()
        {
            if (relayManager == null)
            {
                Debug.LogError("[NetworkMenu] RelayManager is not assigned!");
                return;
            }

            string joinCode = joinCodeInputField.text.Trim().ToUpper();
            
            if (string.IsNullOrEmpty(joinCode))
            {
                Debug.LogWarning("[NetworkMenu] Join code is empty");
                return;
            }

            Debug.Log($"[NetworkMenu] Attempting to join room with code: {joinCode}");
            
            // Show waiting state
            ShowWaitingRoom("Joining room...", "");
            
            // Join room via Relay
            bool success = await relayManager.JoinRoom(joinCode);

            if (success)
            {
                UpdateStatusText("Connected! Waiting for game to start...");
                Debug.Log("[NetworkMenu] Successfully joined room");
            }
            else
            {
                ShowJoinRoomPanel();
                Debug.LogError("[NetworkMenu] Failed to join room");
            }
        }

        private void OnCopyJoinCodeClicked()
        {
            if (relayManager != null)
            {
                string joinCode = relayManager.GetCurrentJoinCode();
                if (!string.IsNullOrEmpty(joinCode))
                {
                    GUIUtility.systemCopyBuffer = joinCode;
                    Debug.Log($"[NetworkMenu] Join code copied to clipboard: {joinCode}");
                }
            }
        }

        private void OnCancelCreateClicked()
        {
            if (relayManager != null)
            {
                relayManager.LeaveRoom();
            }
            ShowMainMenu();
        }

        private void OnCancelJoinClicked()
        {
            ShowMainMenu();
        }

        private void OnLeaveRoomClicked()
        {
            if (relayManager != null)
            {
                relayManager.LeaveRoom();
            }
            ShowMainMenu();
        }

        private void OnStartGameClicked()
        {
            if (NetworkManager.Singleton == null)
            {
                Debug.LogError("[NetworkMenu] NetworkManager.Singleton is null!");
                return;
            }

            if (!NetworkManager.Singleton.IsHost)
            {
                Debug.LogWarning("[NetworkMenu] Only host can start the game!");
                return;
            }

            Debug.Log($"[NetworkMenu] Host starting game, loading scene: {gameSceneName}");
            
            // Use NetworkManager's SceneManager to load scene for all clients
            var status = NetworkManager.Singleton.SceneManager.LoadScene(
                gameSceneName, 
                UnityEngine.SceneManagement.LoadSceneMode.Single
            );
            
            if (status != Unity.Netcode.SceneEventProgressStatus.Started)
            {
                Debug.LogError($"[NetworkMenu] Failed to start scene load. Status: {status}");
            }
            else
            {
                Debug.Log("[NetworkMenu] Scene load initiated successfully");
            }
        }

        private void OnTankSelectionChanged(int index)
        {
            if (NetworkManager.Singleton != null && NetworkManager.Singleton.IsClient)
            {
                var networkGameManager = NetworkManager.Singleton.GetComponent<Tanks.Complete.NetworkGameManager>();
                if (networkGameManager != null)
                {
                    networkGameManager.SetPlayerTankSelectionRpc(index);
                }
            }
        }

        #endregion

        #region Relay Event Handlers

        private void HandleRoomCreated(string joinCode)
        {
            Debug.Log($"[NetworkMenu] Room created event: {joinCode}");
            ShowWaitingRoom($"Room Created!\nJoin Code: {joinCode}", "Waiting for players...");
        }

        private void HandleRoomJoined(bool success)
        {
            if (success)
            {
                Debug.Log("[NetworkMenu] Successfully joined room");
                ShowWaitingRoom("Connected!", "Waiting for game to start...");
            }
            else
            {
                Debug.LogError("[NetworkMenu] Failed to join room");
                ShowJoinRoomPanel();
            }
        }

        private void HandleError(string errorMessage)
        {
            Debug.LogError($"[NetworkMenu] Relay error: {errorMessage}");
            // Could show error popup here
            ShowMainMenu();
        }

        #endregion

        #region Network Callbacks

        private void OnClientConnected(ulong clientId)
        {
            Debug.Log($"[NetworkMenu] Client connected: {clientId}");
            UpdatePlayerList();
        }

        private void OnClientDisconnected(ulong clientId)
        {
            Debug.Log($"[NetworkMenu] Client disconnected: {clientId}");
            
            // If we disconnected, return to main menu
            if (NetworkManager.Singleton != null && clientId == NetworkManager.Singleton.LocalClientId)
            {
                ShowMainMenu();
            }
            else
            {
                UpdatePlayerList();
            }
        }

        #endregion

        #region UI Panel Management

        private void ShowMainMenu()
        {
            SetPanelActive(mainMenuPanel, true);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, false);
        }

        private void ShowCreateRoomPanel()
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, true);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, false);
        }

        private void ShowJoinRoomPanel()
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, true);
            SetPanelActive(waitingRoomPanel, false);
            
            if (joinCodeInputField != null)
            {
                joinCodeInputField.text = "";
            }
        }

        private void ShowWaitingRoom(string status, string playerInfo)
        {
            SetPanelActive(mainMenuPanel, false);
            SetPanelActive(createRoomPanel, false);
            SetPanelActive(joinRoomPanel, false);
            SetPanelActive(waitingRoomPanel, true);
            
            UpdateStatusText(status);
            UpdatePlayerListText(playerInfo);
        }

        private void SetPanelActive(GameObject panel, bool active)
        {
            if (panel != null)
            {
                panel.SetActive(active);
            }
        }

        #endregion

        #region UI Updates

        private void UpdateJoinCodeText(string code)
        {
            if (joinCodeText != null)
            {
                joinCodeText.text = code;
            }
        }

        private void UpdateStatusText(string status)
        {
            if (statusText != null)
            {
                statusText.text = status;
            }
        }

        private void UpdatePlayerListText(string playerInfo)
        {
            if (playerListText != null)
            {
                playerListText.text = playerInfo;
            }
        }

        private void UpdatePlayerList()
        {
            if (NetworkManager.Singleton == null || !NetworkManager.Singleton.IsListening)
            {
                UpdatePlayerListText("Not connected");
                if (startGameButton != null) startGameButton.gameObject.SetActive(false);
                return;
            }

            int connectedPlayers = NetworkManager.Singleton.ConnectedClientsList.Count;
            string playerText = $"Players: {connectedPlayers}";
            
            bool isHost = false;
            if (relayManager != null && relayManager.IsHost())
            {
                playerText += " (You are Host)";
                isHost = true;
            }
            
            UpdatePlayerListText(playerText);
            
            if (startGameButton != null)
            {
                startGameButton.gameObject.SetActive(isHost);
            }
        }

        #endregion

        #region Legacy Support (for backwards compatibility)

        // Keep old methods for scenes that might reference them
        [Obsolete("Use Create/Join Room buttons instead")]
        private void Hide()
        {
            gameObject.SetActive(false);
        }

        #endregion
    }

